    const culture = await getHomeSettings();
    if (culture) {
      console.log('Culture video: ' + (culture.videoId || 'none set'));
      $w(EL).setAttribute('data-culture', JSON.stringify(culture));
    }
  } catch (err) {
    console.error('Culture load failed:', err);
