/* ===========================================================================
   ARISE CHURCH — SAMPLE SITE SERVER
   Zero-dependency local server that renders the Velo custom elements the way
   the published Wix site does: header + page element + footer, with clean
   URLs (/about, /leaders, ...) and a mock of the Velo HTTP function that the
   forms POST to (/_functions/ariseForm).

   Run:   node sample-site/server.js
   Open:  http://localhost:4173/_sample   (hub page listing every route)

   This is a local render of the code in files2/arise-fixed-2026-08-23. It is
   NOT the live site and it does not talk to Wix.
   =========================================================================== */
'use strict';
const http = require('http');
const fs   = require('fs');
const path = require('path');

const ROOT = __dirname;
const PORT = Number(process.env.PORT) || 4173;

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js':   'text/javascript; charset=utf-8',
  '.css':  'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png':  'image/png',
  '.jpg':  'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.svg':  'image/svg+xml',
  '.ico':  'image/x-icon',
  '.txt':  'text/plain; charset=utf-8'
};

/* Mirrors backend/http-functions.js as described in ARISE-HANDOFF.md §5a:
   the ALLOWED list, the trim/slice clean(), the single-backslash email regex,
   and "name and email required". */
const ALLOWED = ['contact', 'serve', 'prayer', 'connect-host', 'connect-join'];
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
function clean(v, max) { return String(v == null ? '' : v).trim().slice(0, max || 2000); }

const submissions = [];   // in-memory only; printed to the console

function send(res, code, body, type, extra) {
  const headers = Object.assign({
    'Content-Type': type || 'text/plain; charset=utf-8',
    'Cache-Control': 'no-store',
    'X-Arise-Sample': '1'
  }, extra || {});
  res.writeHead(code, headers);
  res.end(body);
}

function serveFile(res, file, code) {
  const ext = path.extname(file).toLowerCase();
  fs.readFile(file, (err, data) => {
    if (err) return send(res, 500, 'read error: ' + file);
    send(res, code || 200, data, MIME[ext] || 'application/octet-stream');
  });
}

/* Clean URL -> generated page file. Mirrors the routes in build.js. */
function pageFor(pathname) {
  let p = pathname.replace(/\/+$/, '') || '/';
  if (p === '/') return 'index.html';
  if (p.startsWith('/events-1/')) return '_app-event-detail.html';
  if (p.startsWith('/classes/'))  return '_app-class-detail.html';
  return p.slice(1).replace(/\//g, '-') + '.html';
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const pathname = decodeURIComponent(url.pathname);

  /* ---- mock Velo HTTP function --------------------------------------- */
  if (pathname === '/_functions/ariseForm') {
    if (req.method !== 'POST') return send(res, 405, 'POST only');
    let raw = '';
    req.on('data', (c) => { raw += c; if (raw.length > 1e6) req.destroy(); });
    req.on('end', () => {
      let body = {};
      try { body = JSON.parse(raw || '{}'); } catch (e) {
        return send(res, 400, JSON.stringify({ error: 'bad json' }), MIME['.json']);
      }
      const formType = clean(body.formType, 40).toLowerCase();
      if (!ALLOWED.includes(formType)) {
        console.log('[form] REJECTED unknown formType:', JSON.stringify(formType));
        return send(res, 400, JSON.stringify({ error: 'unknown form' }), MIME['.json']);
      }
      const name = clean(body.name, 120), email = clean(body.email, 200);
      if (!name || !email) {
        console.log('[form] REJECTED missing name/email for', formType);
        return send(res, 400, JSON.stringify({ error: 'name and email required' }), MIME['.json']);
      }
      if (!EMAIL_RE.test(email)) {
        console.log('[form] REJECTED invalid email', JSON.stringify(email));
        return send(res, 400, JSON.stringify({ error: 'invalid email' }), MIME['.json']);
      }
      const record = {
        formType, name, email,
        phone: clean(body.phone, 60), subject: clean(body.subject, 200),
        position: clean(body.position, 120), message: clean(body.message, 4000),
        handled: false, receivedAt: new Date().toISOString()
      };
      submissions.push(record);
      console.log('[form] SAVED', JSON.stringify(record));
      return send(res, 200, JSON.stringify({ ok: true }), MIME['.json']);
    });
    return;
  }

  /* Anything else under /_functions/ would 404 on Wix too. */
  if (pathname.startsWith('/_functions/')) {
    return send(res, 404, JSON.stringify({ error: 'no such function' }), MIME['.json']);
  }

  /* ---- the sample's own inspection endpoint ---------------------------- */
  if (pathname === '/_sample/submissions.json') {
    return send(res, 200, JSON.stringify(submissions, null, 2), MIME['.json']);
  }

  /* ---- static assets --------------------------------------------------- */
  const staticPrefixes = ['/elements/', '/assets/'];
  const staticFiles = ['/fixtures.js', '/mock-page-code.js', '/sample.css'];
  if (staticPrefixes.some((p) => pathname.startsWith(p)) || staticFiles.includes(pathname)) {
    const file = path.join(ROOT, pathname);
    if (!file.startsWith(ROOT)) return send(res, 403, 'forbidden');
    if (!fs.existsSync(file)) return send(res, 404, 'not found: ' + pathname);
    return serveFile(res, file);
  }

  /* ---- pages ----------------------------------------------------------- */
  const page = path.join(ROOT, 'pages', pageFor(pathname));
  if (fs.existsSync(page)) {
    console.log('[page] 200', pathname);
    return serveFile(res, page);
  }

  const ref = req.headers.referer ? '  (from ' + req.headers.referer + ')' : '';
  console.log('[page] 404', pathname + ref);
  return serveFile(res, path.join(ROOT, 'pages', '_404.html'), 404);
});

server.listen(PORT, () => {
  console.log('Arise Church sample site  ->  http://localhost:' + PORT + '/_sample');
});

/* ===========================================================================
   MOCK VELO PAGE CODE
   On the live site, each page's Velo code queries the backend and then sets
   data-* attributes on the custom element (ARISE-HANDOFF.md §3, §5c). This
   file plays that role in the sample: it waits for the element to be defined,
   waits a beat (page code arrives after the element has already rendered its
   built-in fallback, exactly as in production), then sets the attributes from
   window.ARISE_FIXTURES.

   The header and footer are NOT fed data-content here, because none of the
   documented page code does that on the live site either (masterPage.js is
   empty). They render their built-in text, as they do in production.
   =========================================================================== */
(function () {
  'use strict';
  var cfg = window.__ARISE_PAGE__ || {};
  var F   = window.ARISE_FIXTURES || {};
  var delay = typeof cfg.delay === 'number' ? cfg.delay : 350;

  function setAttrs(tag, attrs) {
    var els = document.querySelectorAll(tag);
    if (!els.length) { console.warn('[mock page code] no <' + tag + '> on this page'); return; }
    els.forEach(function (el) {
      Object.keys(attrs).forEach(function (k) { el.setAttribute(k, attrs[k]); });
    });
    console.log('[mock page code] <' + tag + '> got', Object.keys(attrs).join(', '));
  }

  function feed(tag, attrs) {
    if (!window.customElements) return;
    customElements.whenDefined(tag).then(function () {
      setTimeout(function () { setAttrs(tag, attrs); }, delay);
    });
  }

  if (!cfg.tag) return;

  var attrs = {};
  /* cfg.attrs maps attribute name -> fixture key (JSON-stringified, like the
     real page code does with JSON.stringify(result)). */
  Object.keys(cfg.attrs || {}).forEach(function (attr) {
    var key = cfg.attrs[attr];
    if (F[key] === undefined) { console.warn('[mock page code] no fixture "' + key + '" for ' + attr); return; }
    attrs[attr] = JSON.stringify(F[key]);
  });
  /* cfg.raw maps attribute name -> literal string value (e.g. data-series-active="true"). */
  Object.keys(cfg.raw || {}).forEach(function (attr) { attrs[attr] = String(cfg.raw[attr]); });

  /* Every page's code is documented to also send the PageContent map
     (PAGECONTENT-SETUP.md §2). */
  if (cfg.content !== false && F.pageContent) attrs['data-content'] = JSON.stringify(F.pageContent);

  feed(cfg.tag, attrs);

  /* Optional second element on the page (e.g. arise-service-times in the hero). */
  (cfg.extra || []).forEach(function (x) {
    var a = {};
    Object.keys(x.attrs || {}).forEach(function (attr) {
      if (F[x.attrs[attr]] !== undefined) a[attr] = JSON.stringify(F[x.attrs[attr]]);
    });
    Object.keys(x.raw || {}).forEach(function (attr) { a[attr] = String(x.raw[attr]); });
    if (Object.keys(a).length) feed(x.tag, a);
  });
})();

/* ===========================================================================
   SAMPLE SITE PAGE BUILDER
   Generates one HTML page per route into sample-site/pages/. Every page is
   the same composition the published Wix site uses: the header element in a
   #0A0A0C header strip, one page element, the footer element in a #0A0A0C
   footer strip (INSTALL-ORDER.md steps 1, 2 and 4).

   Run:  node sample-site/build.js
   =========================================================================== */
'use strict';
const fs = require('fs');
const path = require('path');

const OUT = path.join(__dirname, 'pages');
fs.mkdirSync(OUT, { recursive: true });

/* ------------------------------------------------------------------------
   ROUTES
   status: 'live'      = page exists on arisecenla.church with this element
           'pending'   = page exists live but the element is not installed yet
           'proposed'  = page recommended by the docs, not created on Wix
           'sample'    = exists only in this sample (to exercise an element)
           'app'       = Wix app page, stand-in only
   ------------------------------------------------------------------------ */
const ROUTES = [
  { path: '/',                title: 'Home',                tag: 'arise-home',        status: 'live',
    attrs: { 'data-photos': 'homePhotos', 'data-news': 'homeNews', 'data-culture': 'homeCulture' },
    hero: true },
  { path: '/about',           title: 'About',               tag: 'arise-about',       status: 'live' },
  { path: '/leaders',         title: 'Meet our Leaders',    tag: 'arise-leaders',     status: 'live',
    attrs: { 'data-leaders': 'leaders' } },
  { path: '/ministries',      title: 'Ministries',          tag: 'arise-ministries',  status: 'live',
    attrs: { 'data-ministries': 'ministries' } },
  { path: '/sermons',         title: 'Sermons',             tag: 'arise-sermons',     status: 'live',
    raw: { 'data-series-active': 'true', 'data-series-title': 'The Believers Authority',
           'data-series-line': '', 'data-series-link': 'https://www.youtube.com/@arisechurch4147/playlists',
           'data-series-button': 'Watch the Series', 'data-live-video': '' } },
  { path: '/events',          title: 'Events',              tag: 'arise-events',      status: 'live',
    attrs: { 'data-events': 'events' } },
  { path: '/contact',         title: 'Contact',             tag: 'arise-contact',     status: 'live' },
  { path: '/arise-bible',     title: 'Bible Search',        tag: 'arise-bible',       status: 'live' },
  { path: '/serve',           title: 'Serve',               tag: 'arise-serve',       status: 'live',
    attrs: { 'data-positions': 'servePositions' } },
  { path: '/connect-groups',  title: 'Connect Groups',      tag: 'arise-connect',     status: 'live',
    attrs: { 'data-groups': 'connectGroups' } },
  { path: '/classes',         title: 'Classes',             tag: 'arise-classes',     status: 'live',
    attrs: { 'data-classes': 'classes' } },
  { path: '/creative-arts',   title: 'Arise Creative Arts', tag: 'arise-creatives',   status: 'live',
    attrs: { 'data-depts': 'creativeDepts', 'data-members': 'creativeMembers' } },
  ...['praise-worship', 'musicians', 'production', 'sound', 'media-team', 'content'].map((slug) => ({
    path: '/' + slug, title: 'Creative Arts · ' + slug, tag: 'arise-creatives', status: 'live',
    fixed: { 'data-dept': slug },
    attrs: { 'data-depts': 'creativeDepts', 'data-members': 'creativeMembers' } })),
  { path: '/childrens',       title: "Children's Ministry", tag: 'arise-childrens',   status: 'live',
    attrs: { 'data-photos': 'galleryChildrens' } },
  { path: '/youth',           title: 'Youth Ministry',      tag: 'arise-youth',       status: 'live',
    attrs: { 'data-photos': 'galleryYouth' } },
  { path: '/outreach',        title: 'Outreach',            tag: 'arise-outreach',    status: 'live',
    attrs: { 'data-photos': 'galleryOutreach' } },
  { path: '/lead-network',    title: 'Lead Network',        tag: 'arise-leadnetwork', status: 'live',
    attrs: { 'data-photos': 'galleryLeadNetwork' } },
  { path: '/arise-alexandria', title: 'Arise Church Alexandria', tag: 'arise-alexandria', status: 'pending' },
  { path: '/prayer',          title: 'Prayer Request',      tag: 'arise-form',        status: 'proposed',
    fixed: { 'data-form': 'prayer' }, content: false,
    note: 'Recommended in AUDIT-REPORT.md (flag 3). Does not exist on the live site; Home and the footer still use mailto: links.' },
  { path: '/_sample/form-contact', title: 'arise-form · contact variant', tag: 'arise-form', status: 'sample',
    fixed: { 'data-form': 'contact' }, content: false },
  { path: '/_sample/form-serve',   title: 'arise-form · serve variant',   tag: 'arise-form', status: 'sample',
    fixed: { 'data-form': 'serve' }, content: false },
  { path: '/_sample/service-times', title: 'arise-service-times · alone', tag: 'arise-service-times', status: 'sample',
    content: false, standalone: true }
];

/* Stand-in pages for routes that are redirects or Wix app pages on the live site. */
const STANDINS = [
  { path: '/tithes-and-offerings', file: 'tithes-and-offerings.html', title: 'Give',
    body: 'On the live site this URL is a <b>301 redirect to Tithe.ly</b> (AUDIT-REPORT.md, live verification). The sample stops here instead of sending you off-site.' },
  { path: '/podcast', file: 'podcast.html', title: 'Podcast',
    body: 'On the live site this URL is a <b>301 redirect to Spotify</b>. The sample stops here instead of sending you off-site.' },
  { path: '/events-1/*', file: '_app-event-detail.html', title: 'Event details',
    body: 'On the live site this is the <b>Wix Events</b> detail and RSVP page for the event you clicked. It is a Wix app page, not one of the custom elements, so the sample cannot render it.' },
  { path: '/classes/*', file: '_app-class-detail.html', title: 'Class details',
    body: 'On the live site this would be the <b>Wix Online Programs</b> page for the class you clicked. It is a Wix app page, not one of the custom elements, so the sample cannot render it.' }
];

const BASE_CSS = `
:root{color-scheme:light only}
html,body{margin:0;padding:0;background:#ffffff;color:#0A0A0C}
.wx-header{background:#0A0A0C}
.wx-footer{background:#0A0A0C}
.wx-hero-wrap{position:relative}
.wx-st{position:absolute;top:96px;right:24px;width:360px;z-index:5}
@media (max-width:900px){.wx-st{position:static;width:auto;padding:12px 16px;background:#0A0A0C}}
.wx-smp{position:fixed;left:12px;bottom:12px;z-index:2147483001;font:600 11px/1 Arial,Helvetica,sans-serif;
  letter-spacing:.12em;text-transform:uppercase;background:#0A0A0C;color:#ffffff;border:1px solid #D6222D;
  padding:9px 12px;border-radius:999px;opacity:.88;text-decoration:none}
.wx-smp:hover{opacity:1}
.wx-standin{max-width:720px;margin:0 auto;padding:96px 24px;font:300 17px/1.6 Oswald,Helvetica,Arial,sans-serif;color:#0A0A0C;background:#ffffff}
.wx-standin h1{font:400 44px/1.02 Anton,Impact,sans-serif;text-transform:uppercase;letter-spacing:.06em;margin:0 0 24px}
.wx-standin .k{color:#D6222D;font:500 12px/1 Oswald,Helvetica,Arial,sans-serif;letter-spacing:.3em;text-transform:uppercase;display:block;margin-bottom:16px}
.wx-standin a{color:#D6222D}
`;

function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }

function shell({ title, main, scripts, cfg, noChrome }) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light">
<title>${esc(title)} · Arise Church (sample render)</title>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Anton&family=Oswald:wght@300;400;500;600&display=swap">
<style>${BASE_CSS}</style>
</head>
<body>
${noChrome ? '' : '<div class="wx-header"><arise-header></arise-header></div>'}
${main}
${noChrome ? '' : '<div class="wx-footer"><arise-footer></arise-footer></div>'}
<a class="wx-smp" href="/_sample" title="Sample site hub: every page in one list">Sample · all pages</a>
<script>window.__ARISE_PAGE__ = ${JSON.stringify(cfg || {})};</script>
<script src="/fixtures.js"></script>
${noChrome ? '' : '<script type="module" src="/elements/arise-header.js"></script>\n<script type="module" src="/elements/arise-footer.js"></script>'}
${scripts.map((s) => `<script type="module" src="/elements/${s}.js"></script>`).join('\n')}
<script src="/mock-page-code.js"></script>
</body>
</html>
`;
}

function fileFor(p) {
  if (p === '/') return 'index.html';
  return p.slice(1).replace(/\//g, '-') + '.html';
}

function attrString(fixed) {
  return Object.keys(fixed || {}).map((k) => ` ${k}="${esc(fixed[k])}"`).join('');
}

/* ---- element pages ------------------------------------------------------- */
for (const r of ROUTES) {
  const tagHtml = `<${r.tag}${attrString(r.fixed)}></${r.tag}>`;
  let main = tagHtml;
  const scripts = [r.tag];
  const cfg = { tag: r.tag, attrs: r.attrs || {}, raw: r.raw || {}, content: r.content !== false };

  if (r.hero) {
    /* On the live site arise-service-times is a second custom element placed
       top-right of the hero, 360×80 (FINAL-BUILD-PLAN.md §10). */
    main = `<div class="wx-hero-wrap">${tagHtml}<div class="wx-st"><arise-service-times></arise-service-times></div></div>`;
    scripts.push('arise-service-times');
  }
  if (r.standalone) {
    main = `<div style="background:#0A0A0C;padding:48px 24px;min-height:60vh"><div style="max-width:360px;margin-left:auto">${tagHtml}</div></div>`;
  }

  fs.writeFileSync(path.join(OUT, fileFor(r.path)), shell({ title: r.title, main, scripts, cfg }));
}

/* ---- stand-ins ----------------------------------------------------------- */
for (const s of STANDINS) {
  const main = `<main class="wx-standin"><span class="k">Sample stand-in</span><h1>${esc(s.title)}</h1><p>${s.body}</p><p><a href="/_sample">Back to the sample hub</a></p></main>`;
  fs.writeFileSync(path.join(OUT, s.file), shell({ title: s.title, main, scripts: [], cfg: {} }));
}

/* ---- 404 ------------------------------------------------------------------ */
fs.writeFileSync(path.join(OUT, '_404.html'), shell({
  title: 'Not in the sample',
  main: `<main class="wx-standin"><span class="k">404 in the sample</span><h1>No page here</h1>
<p>This route has no page in the sample. If you got here by clicking a link inside one of the elements, that link points at a URL the rebuild does not cover — check whether it exists on the live site.</p>
<p><a href="/_sample">Back to the sample hub</a></p></main>`,
  scripts: [], cfg: {}
}));

/* ---- hub ------------------------------------------------------------------ */
const STATUS_LABEL = {
  live: 'Live on arisecenla.church with this element',
  pending: 'Page is live, element not installed yet',
  proposed: 'Recommended page, does not exist on Wix yet',
  sample: 'Sample-only page to exercise an element',
  app: 'Wix app page'
};
const rows = ROUTES.map((r) => `<tr><td><a href="${esc(r.path)}">${esc(r.path)}</a></td><td>${esc(r.title)}</td><td><code>&lt;${esc(r.tag)}${esc(attrString(r.fixed))}&gt;</code></td><td class="s-${r.status}">${esc(STATUS_LABEL[r.status])}${r.note ? '<br><small>' + esc(r.note) + '</small>' : ''}</td></tr>`).join('\n');
const standinRows = STANDINS.map((s) => `<tr><td><a href="${esc(s.path.replace('*', 'sample'))}">${esc(s.path)}</a></td><td>${esc(s.title)}</td><td>—</td><td class="s-app">Stand-in for a redirect or Wix app page</td></tr>`).join('\n');

const hub = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light">
<title>Arise Church sample site · hub</title>
<style>
:root{color-scheme:light only}body{margin:0;background:#F4F2F0;color:#0A0A0C;font:15px/1.5 Oswald,Helvetica,Arial,sans-serif}
.wrap{max-width:1100px;margin:0 auto;padding:48px 24px}
h1{font:400 44px/1.02 Anton,Impact,sans-serif;text-transform:uppercase;letter-spacing:.06em;margin:0 0 8px}
.k{color:#D6222D;font-weight:500;font-size:12px;letter-spacing:.3em;text-transform:uppercase;display:block;margin-bottom:16px}
p{max-width:760px}
table{width:100%;border-collapse:collapse;background:#fff;margin-top:24px;font-size:14px}
th,td{text-align:left;padding:10px 12px;border-bottom:1px solid #E6E4E2;vertical-align:top}
th{background:#0A0A0C;color:#fff;font-weight:500;letter-spacing:.08em;text-transform:uppercase;font-size:11px}
code{font:12px/1.4 Consolas,Menlo,monospace;background:#F4F2F0;padding:2px 5px}
a{color:#D6222D}
.s-live{color:#1c7c3a}.s-pending{color:#b26a00}.s-proposed{color:#6A6A6E}.s-sample{color:#6A6A6E}.s-app{color:#6A6A6E}
.tip{background:#fff;border-left:5px solid #D6222D;padding:16px 20px;margin:24px 0}
</style></head><body><div class="wrap">
<span class="k">Arise Church · local sample</span>
<h1>Every page, one list</h1>
<p>This is a local render of the Velo custom elements from <code>files2/arise-fixed-2026-08-23</code>, composed the way the published Wix site composes them (header + page element + footer). Content that the live site pulls from the CMS is supplied from fixtures. Forms post to a mock of <code>/_functions/ariseForm</code> and are printed to the server console.</p>
<div class="tip"><b>Not the live site.</b> Nothing here touches Wix. Photos load from the church's Wix media CDN, so you need to be online to see them.</div>
<table><thead><tr><th>URL</th><th>Page</th><th>Element</th><th>Status</th></tr></thead><tbody>
${rows}
${standinRows}
</tbody></table>
<p style="margin-top:32px"><a href="/_sample/submissions.json">Form submissions received by the mock backend (JSON)</a></p>
</div></body></html>`;
fs.writeFileSync(path.join(OUT, '_sample.html'), hub);

console.log('built ' + (ROUTES.length + STANDINS.length + 2) + ' pages into ' + OUT);

{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "arise-sample",
      "runtimeExecutable": "node",
      "runtimeArgs": ["sample-site/server.js"],
      "port": 4173
    }
  ]
}

