async () => {
  const cols = ['Leaders', 'Ministries', 'PageContent', 'ConnectGroups', 'ServePositions', 'CreativeDepartments', 'CreativeMembers', 'HomeSettings', 'SiteSettings', 'Studies', 'PastEvents'];
  const url = 'https://www.wixapis.com/wix-data/v2/items/query';
  const out = {};
  const results = await Promise.allSettled(cols.map(async (c) => {
    const body = {
      dataCollectionId: c,
      query: { paging: { limit: 100 } },
      returnTotalCount: true
    };
    const r = await wix.request({ method: 'POST', url: url, body: body });
    const items = (r.dataItems || []).map((d) => d.data || d);
    return { total: r.pagingMetadata ? r.pagingMetadata.total : null, items: items };
  }));
  results.forEach((r, i) => {
    out[cols[i]] = r.status === 'fulfilled' ? r.value : { error: String(r.reason && (r.reason.message || r.reason)) };
  });
  try {
    const fsBody = {
      dataCollectionId: 'FormSubmissions',
      query: { paging: { limit: 100 }, fields: ['formType', 'handled', '_createdDate'] },
      returnTotalCount: true
    };
    const r = await wix.request({ method: 'POST', url: url, body: fsBody });
    out.FormSubmissions = {
      total: r.pagingMetadata ? r.pagingMetadata.total : null,
      items: (r.dataItems || []).map((d) => {
        const x = d.data || d;
        return { formType: x.formType, handled: x.handled, created: x._createdDate };
      })
    };
  } catch (e) {
    out.FormSubmissions = { error: String(e && e.message ? e.message : e) };
  }
  return out;
}

