async () => {
  const url = 'https://www.wixapis.com/wix-data/v2/items/query';
  const body = {
    dataCollectionId: 'PageContent',
    query: { paging: { limit: 100 } },
    returnTotalCount: true
  };
  const r = await wix.request({ method: 'POST', url: url, body: body });
  const rows = (r.dataItems || []).map((d) => d.data || d).map((x) => {
    return {
      k: x.contentKey,
      t: x.text ? String(x.text).slice(0, 160) : '',
      u: x.imageUrl || '',
      i: x.image ? String(x.image).slice(0, 90) : ''
    };
  });
  rows.sort((a, b) => (a.k < b.k ? -1 : 1));
  return { total: r.pagingMetadata ? r.pagingMetadata.total : null, rows: rows };
}

async () => {
  const url = 'https://www.wixapis.com/wix-data/v2/items/query';
  const keep = {
    ConnectGroups: ['title', 'hostName', 'day', 'time', 'location', 'dates', 'description', 'flyer', 'audience', 'isFull', 'active', 'sortOrder'],
    ServePositions: ['title', 'description', 'team', 'image', 'urgent', 'active', 'sortOrder'],
    CreativeDepartments: ['name', 'slug', 'tagline', 'description', 'groupPhoto', 'pageLink', 'active', 'sortOrder'],
    CreativeMembers: ['name', 'department', 'role', 'bio', 'photo', 'isLeader', 'active', 'sortOrder']
  };
  const out = {};
  for (const c of Object.keys(keep)) {
    try {
      const body = { dataCollectionId: c, query: { paging: { limit: 100 } }, returnTotalCount: true };
      const r = await wix.request({ method: 'POST', url: url, body: body });
      const items = (r.dataItems || []).map((d) => d.data || d).map((x) => {
        const o = {};
        keep[c].forEach((f) => { if (x[f] !== undefined && x[f] !== '') o[f] = typeof x[f] === 'string' ? x[f].slice(0, 140) : x[f]; });
        return o;
      });
      out[c] = { total: r.pagingMetadata ? r.pagingMetadata.total : null, items: items };
    } catch (e) {
      out[c] = { error: String(e && e.message ? e.message : e).slice(0, 200) };
    }
  }
  return out;
}

async () => {
  const url = 'https://www.wixapis.com/wix-data/v2/items/query';
  const cols = ['HomeSettings', 'SiteSettings', 'Studies', 'PastEvents'];
  const out = {};
  for (const c of cols) {
    try {
      const body = { dataCollectionId: c, query: { paging: { limit: 50 } }, returnTotalCount: true };
      const r = await wix.request({ method: 'POST', url: url, body: body });
      const items = (r.dataItems || []).map((d) => d.data || d).map((x) => {
        const o = {};
        Object.keys(x).forEach((f) => {
          if (f.startsWith('_')) return;
          o[f] = typeof x[f] === 'string' ? x[f].slice(0, 140) : x[f];
        });
        return o;
      });
      out[c] = { total: r.pagingMetadata ? r.pagingMetadata.total : null, items: items };
    } catch (e) {
      out[c] = { error: String(e && e.message ? e.message : e).slice(0, 200) };
    }
  }
  try {
    const fsBody = {
      dataCollectionId: 'FormSubmissions',
      query: { paging: { limit: 100 }, fields: ['formType', 'handled', '_createdDate'] },
      returnTotalCount: true
    };
    const r = await wix.request({ method: 'POST', url: url, body: fsBody });
    const byType = {};
    (r.dataItems || []).map((d) => d.data || d).forEach((x) => {
      const key = String(x.formType || 'unknown') + (x.handled ? ' (handled)' : ' (unhandled)');
      byType[key] = (byType[key] || 0) + 1;
    });
    out.FormSubmissions = { total: r.pagingMetadata ? r.pagingMetadata.total : null, byType: byType };
  } catch (e) {
    out.FormSubmissions = { error: String(e && e.message ? e.message : e).slice(0, 200) };
  }
  return out;
}

async () => {
  const url = 'https://www.wixapis.com/wix-data/v2/items/query';
  const tryIds = ['Portfolio/ProjectItems', 'PortfolioProjectItems'];
  const out = { tried: [] };
  for (const id of tryIds) {
    try {
      const body = { dataCollectionId: id, query: { paging: { limit: 100 } }, returnTotalCount: true };
      const r = await wix.request({ method: 'POST', url: url, body: body });
      const items = (r.dataItems || []).map((d) => d.data || d).map((x) => {
        const img = x.image && x.image.imageInfo ? String(x.image.imageInfo) : '';
        const vid = x.video && x.video.videoInfo ? String(x.video.videoInfo) : '';
        const imgId = img.indexOf('wix:image://v1/') === 0 ? img.split('wix:image://v1/')[1].split('/')[0] : img.slice(0, 60);
        const vidId = vid.indexOf('wix:video://v1/') === 0 ? vid.split('wix:video://v1/')[1].split('/')[0] : '';
        const posterMatch = vid.match(/posterUri=([^&]+)/);
        const proj = x.project;
        const projId = typeof proj === 'string' ? proj : (proj && (proj._id || proj.id)) || '';
        return {
          p: String(projId).slice(0, 8),
          ty: x.type || '',
          im: imgId,
          vi: vidId,
          po: posterMatch ? decodeURIComponent(posterMatch[1]).slice(0, 60) : '',
          t: x.title ? String(x.title).slice(0, 50) : '',
          d: x.description ? String(x.description).slice(0, 50) : '',
          s: x.sortOrder
        };
      });
      out.collection = id;
      out.total = r.pagingMetadata ? r.pagingMetadata.total : null;
      out.items = items;
      return out;
    } catch (e) {
      out.tried.push(id + ': ' + String(e && e.message ? e.message : e).slice(0, 160));
    }
  }
  return out;
}

