/* Dev-only helper for the render audit of the sample site. Not part of the
   Wix site. Call window.__audit() from the browser console. */
window.__audit = function () {
  var r = { url: location.pathname, vw: innerWidth, overflow: Math.max(0, document.documentElement.scrollWidth - innerWidth),
    h1: 0, headings: [], els: [], dupIds: [], noAlt: [], brokenImgs: [], smallTaps: [], contrast: [] };
  document.querySelectorAll('*').forEach(function (e) {
    if (e.tagName.indexOf('-') > -1) r.els.push(e.tagName.toLowerCase() + (e.children.length ? '' : '(EMPTY)'));
  });
  r.headings = Array.prototype.slice.call(document.querySelectorAll('h1,h2,h3,h4'))
    .filter(function (h) { return h.getBoundingClientRect().width > 0; })
    .map(function (h) { return h.tagName + ' ' + h.textContent.trim().replace(/\s+/g, ' ').slice(0, 30); });
  r.h1 = document.querySelectorAll('h1').length;
  var ids = {};
  document.querySelectorAll('[id]').forEach(function (e) { ids[e.id] = (ids[e.id] || 0) + 1; });
  r.dupIds = Object.keys(ids).filter(function (k) { return ids[k] > 1; });
  document.querySelectorAll('img').forEach(function (i) {
    var s = i.getAttribute('src') || '';
    if (!i.hasAttribute('alt')) r.noAlt.push(s.slice(-40));
    if (s && i.complete && i.naturalWidth === 0) r.brokenImgs.push(s.replace('https://static.wixstatic.com/media/', '').slice(0, 60) + ' | alt=' + i.alt.slice(0, 30));
  });
  document.querySelectorAll('a,button,[role=button],input,select,textarea,summary').forEach(function (el) {
    var b = el.getBoundingClientRect(); if (!b.width || !b.height) return;
    var cs = getComputedStyle(el); if (cs.visibility === 'hidden' || el.closest('[hidden]')) return;
    if (b.height < 24 || b.width < 24) r.smallTaps.push((el.getAttribute('aria-label') || el.textContent || el.tagName).trim().replace(/\s+/g, ' ').slice(0, 24) + ' ' + Math.round(b.width) + 'x' + Math.round(b.height));
  });
  function lum(c) {
    var m = c.match(/[\d.]+/g); if (!m) return null;
    if (m.length > 3 && Number(m[3]) === 0) return null;
    var f = function (v) { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
    return 0.2126 * f(+m[0]) + 0.7152 * f(+m[1]) + 0.0722 * f(+m[2]);
  }
  function bgOf(el) {
    var e = el;
    while (e && e !== document.documentElement) {
      var cs = getComputedStyle(e);
      if (cs.backgroundImage && cs.backgroundImage !== 'none') return 'IMG';
      var m = cs.backgroundColor.match(/[\d.]+/g);
      if (m && (m.length < 4 || Number(m[3]) > 0.6)) return cs.backgroundColor;
      e = e.parentElement;
    }
    return 'rgb(255, 255, 255)';
  }
  var w = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT); var n; var seen = [];
  while ((n = w.nextNode())) {
    var t = n.textContent.trim(); if (t.length < 2) continue;
    var el = n.parentElement; if (!el || seen.indexOf(el) > -1 || el.closest('script,style,[hidden],.wx-smp')) continue;
    seen.push(el);
    var cs = getComputedStyle(el); if (cs.visibility === 'hidden' || cs.display === 'none' || Number(cs.opacity) === 0) continue;
    var b = el.getBoundingClientRect(); if (!b.width || !b.height) continue;
    var bg = bgOf(el); if (bg === 'IMG') continue;
    var l1 = lum(cs.color), l2 = lum(bg); if (l1 == null || l2 == null) continue;
    var ratio = (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
    var size = parseFloat(cs.fontSize); var bold = parseInt(cs.fontWeight, 10) >= 700;
    var large = size >= 24 || (size >= 18.66 && bold);
    if (ratio < (large ? 3 : 4.5)) r.contrast.push(t.slice(0, 24) + ' ' + ratio.toFixed(2) + ':1 ' + Math.round(size) + 'px ' + cs.color + ' on ' + bg);
  }
  r.smallTapsCount = r.smallTaps.length; r.smallTaps = r.smallTaps.slice(0, 8);
  r.contrastCount = r.contrast.length; r.contrast = r.contrast.slice(0, 10);
  r.headings = r.headings.slice(0, 14);
  return r;
};

