async () => {
  const r = await wix.request({ method: 'GET', url: 'https://www.wixapis.com/wix-data/v2/collections' });
  const cols = r.collections || [];
  const custom = [];
  const app = [];
  cols.forEach((c) => {
    const isApp = c.collectionType && c.collectionType !== 'NATIVE';
    const fields = (c.fields || []).filter((f) => !String(f.key).startsWith('_')).map((f) => {
      const ref = f.typeMetadata && f.typeMetadata.reference ? ' -> ' + f.typeMetadata.reference.referencedCollectionId : '';
      return f.key + ':' + f.type + ref + (f.required ? '!' : '') + (f.systemField ? ' (sys)' : '');
    });
    const p = c.permissions || {};
    const entry = {
      id: c.id,
      name: c.displayName,
      type: c.collectionType,
      perms: [p.read, p.insert, p.update, p.remove].join('/'),
      displayField: c.displayField,
      fields: fields,
      updated: c.updatedDate ? String(c.updatedDate).slice(0, 10) : ''
    };
    if (isApp) app.push({ id: c.id, n: fields.length, type: c.collectionType });
    else custom.push(entry);
  });
  return { total: cols.length, custom: custom, app: app };
}

