(() => {
  const t = document.body.innerText;
  const turns = (t.match(/\nYou said:/g) || []).length;
  const keys = ['imgUrl', 'content.web.js', 'customElement', 'pasted', 'praise-worship', 'data-dept', 'Service Times', 'masterPage', 'http-functions', 'getPageContent', 'Sheron', 'arise-fixed', 'AUDIT-REPORT', 'Publish', 'page code', 'Portfolio', 'events.web', 'Kristina', '10:00', 'Bible Study', 'PageContent', 'label'];
  const hits = {};
  keys.forEach((k) => {
    const re = new RegExp(k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi');
    let m; const arr = []; let n = 0;
    while ((m = re.exec(t)) && n < 200) { n++; if (arr.length < 6) arr.push(t.slice(Math.max(0, m.index - 220), m.index + 260).replace(/\s+/g, ' ')); }
    hits[k] = { count: n, samples: arr };
  });
  return { length: t.length, turns, head: t.slice(0, 300), tail: t.slice(-3500), hits };
})()

