            '<a href="/events" target="_top">Events</a>' +
            '<a href="/arise-bible" target="_top">Bible Search</a>' +
          '</div>' +

          '<div>' +
            '<div class="aft__lbl">Connect</div>' +
            '<a href="/contact" target="_top">Contact</a>' +
            '<a href="/serve" target="_top">Sign Up to Serve</a>' +
