import { fetch } from 'wix-fetch';

const CHANNEL_ID = 'UCGS9j7B_prcJkbTNgzlGrKg';

/* =========================================================================
   1. LIVE STREAM DETECTION
   Reads YouTube's public /live page. When streaming, its canonical link is
   a watch URL. When not, it points back at the channel. No API key needed.
   ========================================================================= */

let liveCache = { value: null, at: 0 };
const LIVE_CACHE_MS = 45000;

export async function getLiveVideoId() {
  const now = Date.now();
  if (now - liveCache.at < LIVE_CACHE_MS) return liveCache.value;

  let result = null;

  try {
    const res = await fetch(
      'https://www.youtube.com/channel/' + CHANNEL_ID + '/live',
      { method: 'get', headers: { 'User-Agent': 'Mozilla/5.0 (compatible)' } }
    );

    if (res.ok) {
      const html = await res.text();

      // Signal 1: when live, the canonical link is a watch URL
      const canonical = html.match(/<link rel="canonical" href="([^"]+)"/);
      if (canonical && canonical[1].indexOf('/watch?v=') > -1) {
        const id = canonical[1].split('/watch?v=')[1].split('&')[0];
        if (/^[A-Za-z0-9_-]{11}$/.test(id)) result = id;
      }

      // Signal 2: fallback if the canonical is missing
      if (!result && html.indexOf('"isLive":true') > -1) {
        const vid = html.match(/"videoId":"([A-Za-z0-9_-]{11})"/);
        if (vid) result = vid[1];
      }
    }
  } catch (err) {
    console.error('Live check failed:', err);
    result = null;
  }

  liveCache = { value: result, at: now };
  return result;
}

/* =========================================================================
   2. CURRENT SERIES
   Reads the channel's playlists. A playlist counts as the current series if
   its name contains "series" -- which four of yours already do. Anything on
   IGNORE is never treated as a series.
   ========================================================================= */

const IGNORE = [
  'sunday sermons',
  'lead network',
  'iserve september',
  'glory nights | arise church',
  'conferences & special events',
  'apostle bryant sanders - messages'
];

let seriesCache = { value: null, at: 0 };
const SERIES_CACHE_MS = 600000;

export async function getCurrentSeries() {
  const now = Date.now();
  if (now - seriesCache.at < SERIES_CACHE_MS) return seriesCache.value;

  let result = null;

  try {
    const res = await fetch(
      'https://www.youtube.com/channel/' + CHANNEL_ID + '/playlists',
      { method: 'get', headers: { 'User-Agent': 'Mozilla/5.0 (compatible)' } }
    );

    if (res.ok) {
      const html = await res.text();
      const seen = {};

      // NOTE: playlist IDs come in two lengths, 13 and 34 characters.
      // Matching {16,} silently misses most of yours.
      const re = /"playlistId":"(PL[A-Za-z0-9_-]{10,})"/g;
      let m;

      while ((m = re.exec(html)) !== null) {
        const pid = m[1];
        if (seen[pid]) continue;
        seen[pid] = true;

        const seg = html.slice(m.index, m.index + 3000);
        const t = seg.match(/"title":\{"runs":\[\{"text":"([^"]{2,90})"/) ||
                  seg.match(/"title":\{"simpleText":"([^"]{2,90})"/);
        if (!t) continue;

        const title = t[1].trim();
        const lower = title.toLowerCase();

        if (IGNORE.indexOf(lower) > -1) continue;
        if (lower.indexOf('series') === -1) continue;   // opt-in by name

        result = {
          // drop a trailing "(Series)" so the heading reads cleanly
          title: title.replace(/\s*\(series\)\s*$/i, '').trim(),
          url: 'https://www.youtube.com/playlist?list=' + pid
        };
        break;                                          // first match = newest
      }
    }
  } catch (err) {
    console.error('Series lookup failed:', err);
    result = null;
  }

  seriesCache = { value: result, at: now };
  return result;
}

import { ok, badRequest, serverError } from 'wix-http-functions';
import wixData from 'wix-data';
import { contacts } from 'wix-crm-backend';
import { customTrigger } from '@wix/automations';
import { auth } from '@wix/essentials';

const TRIGGER_ID = '519d3164-8dae-4448-a362-35ff96ed2068';

/* Add a form type here before the element can use it. */
const ALLOWED = ['contact', 'serve', 'prayer', 'connect-host', 'connect-join'];

function clean(v, max) {
  return String(v == null ? '' : v).trim().slice(0, max || 2000);
}

export async function post_ariseForm(request) {
  try {
    const body = await request.body.json();

    const formType = clean(body.formType, 40).toLowerCase();
    if (ALLOWED.indexOf(formType) === -1) {
      return badRequest({ body: { error: 'unknown form' } });
    }

    const name    = clean(body.name, 120);
    const email   = clean(body.email, 200);
    const message = clean(body.message, 4000);

    if (!name || !email) return badRequest({ body: { error: 'name and email required' } });
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      return badRequest({ body: { error: 'invalid email' } });
    }

    const record = {
      formType: formType,
      name: name,
      email: email,
      phone:    clean(body.phone, 60),
      // connect-host / connect-join use these two for area and preferred day
      subject:  clean(body.subject, 200),
      position: clean(body.position, 120),
      message:  message,
      handled:  false
    };

    // 1. Store it first -- nothing is lost even if everything below fails.
    await wixData.insert('FormSubmissions', record, { suppressAuth: true });

    // 2. Add the sender to Contacts so they appear in your Inbox.
    let contactId = null;
    try {
      const parts = name.split(' ');
      const res = await contacts.appendOrCreateContact({
        name: { first: parts[0] || name, last: parts.slice(1).join(' ') || '' },
        emails: [{ email: email, primary: true, tag: 'MAIN' }],
        phones: record.phone ? [{ phone: record.phone, primary: true, tag: 'MOBILE' }] : []
      });
      contactId = res.contactId;
    } catch (cErr) {
      console.error('Contact create failed (submission still saved):', cErr);
    }

    // 3. Fire the automation.
    try {
      const runTrigger = auth.elevate(customTrigger.runTrigger);
      const payload = {
        formType: formType,
        name: name,
        email: email,
        phone:    record.phone    || '-',
        subject:  record.subject  || '-',
        position: record.position || '-',
        message:  message || '-'
      };
      if (contactId) payload.contactId = contactId;

      await runTrigger({ triggerId: TRIGGER_ID, payload: payload });
      console.log('Automation fired:', formType);
    } catch (tErr) {
      console.error('Automation trigger failed:', tErr);
    }

    return ok({ body: { ok: true } });

  } catch (err) {
    console.error('ariseForm failed:', err);
    return serverError({ body: { error: 'server error' } });
  }
}

