        const seg = html.slice(m.index, m.index + 3000);
        const t = seg.match(/"title":\{"runs":\[\{"text":"([^"]{2,90})"/) ||
                  seg.match(/"title":\{"simpleText":"([^"]{2,90})"/);
        if (!t) continue;

        const title = t[1].trim();
        const lower = title.toLowerCase();

        if (IGNORE.indexOf(lower) > -1) continue;
        if (lower.indexOf('series') === -1) continue;   // opt-in by name

        result = {
          // drop a trailing "(Series)" so the heading reads cleanly
          title: title.replace(/\s*\(series\)\s*$/i, '').trim(),
          url: 'https://www.youtube.com/playlist?list=' + pid
        };
        break;                                          // first match = newest
      }
    }
  } catch (err) {
    console.error('Series lookup failed:', err);
    result = null;
  }

  seriesCache = { value: result, at: now };
  return result;
}

import { Permissions, webMethod } from 'wix-web-module';
import { projectItems } from '@wix/portfolio';
import { auth } from '@wix/essentials';

function fromImage(info) {
  if (typeof info !== 'string') return '';
  if (info.indexOf('wix:image://') !== 0) return info;
  const id = info.split('wix:image://v1/')[1].split('/')[0].split('#')[0];
  return 'https://static.wixstatic.com/media/' + id;
}

function fromVideo(info) {
  if (typeof info !== 'string' || info.indexOf('wix:video://') !== 0) {
    return { id: '', poster: '' };
  }
  const id = info.split('wix:video://v1/')[1].split('/')[0];
  const hash = info.split('#')[1] || '';
  const m = hash.match(/posterUri=([^&]+)/);
  return {
    id: id,
    poster: m ? 'https://static.wixstatic.com/media/' + decodeURIComponent(m[1]) : ''
  };
}

export const getProjectPhotos = webMethod(
  Permissions.Anyone,
  async (projectId) => {
    try {
      const list = auth.elevate(projectItems.listProjectItems);
      const res = await list(projectId);
      const items = res.items || [];

      return items.map((it) => {
        if (it.type === 'VIDEO') {
          const v = fromVideo(it.video && it.video.videoInfo);
          return { src: v.poster, videoId: v.id, alt: it.title || '', caption: it.description || '' };
        }
        return {
          src: fromImage(it.image && it.image.imageInfo),
          alt: it.title || '',
          caption: it.description || ''
        };
      }).filter((p) => p.src || p.videoId);

    } catch (err) {
      console.error('getProjectPhotos failed for ' + projectId + ':', err);
      return [];
    }
  }
);

import { Permissions, webMethod } from 'wix-web-module';
import { programs } from '@wix/online-programs';
import { auth } from '@wix/essentials';

function fromImage(info) {
  if (typeof info !== 'string') return '';
  if (info.indexOf('wix:image://') !== 0) return info;
  const id = info.split('wix:image://v1/')[1].split('/')[0].split('#')[0];
  return 'https://static.wixstatic.com/media/' + id;
}

export const getPrograms = webMethod(
  Permissions.Anyone,
  async () => {
    try {
      const query = auth.elevate(programs.queryPrograms);
      const res = await query().eq('status', 'PUBLISHED').find();
      const items = res.items || res.programs || [];

      if (items.length) {
        console.log('Programs: first ->', JSON.stringify(items[0]).slice(0, 1500));
      }

      return items.map((p) => {
        const d = p.description || {};
        const media = d.media || d.image || {};
        const rawImg = typeof media === 'string'
          ? media
          : (media.image || media.url || media.imageInfo || '');
        const price = p.price && p.price.value
          ? (p.price.currency === 'USD' ? '$' : '') + p.price.value
          : 'Free';

        return {
          id: p.id,
          title: d.title || '',
          details: d.details || '',
          image: fromImage(rawImg),
          price: price,
          steps: p.stepCount || 0,
          sections: p.sectionCount || 0,
          selfPaced: !!(p.timeline && p.timeline.selfPaced),
          url: (p.seo && p.seo.slug) ? '/class-detail/' + p.seo.slug : ''
        };
      });

    } catch (err) {
      console.error('getPrograms failed:', err);
      return [];
    }
  }
);

import { events } from 'wix-events.v2';
import { elevate } from 'wix-auth';

const elevatedQuery = elevate(events.queryEvents);

function ctaFor(ev) {
  const reg = ev.registration || {};
  const type = reg.type;
  const status = reg.status || '';

  if (reg.registrationDisabled) return { cta: 'View Event', ctaEnabled: true };

  if (type === 'TICKETING') {
    if (reg.tickets && reg.tickets.soldOut) return { cta: 'Sold Out', ctaEnabled: false };
    if (status.indexOf('OPEN') === 0) return { cta: 'Get Tickets', ctaEnabled: true };
    return { cta: 'View Event', ctaEnabled: true };
  }
  if (type === 'RSVP') {
    if (status === 'OPEN_RSVP_WAITLIST') return { cta: 'Join Waitlist', ctaEnabled: true };
    if (status.indexOf('OPEN') === 0) return { cta: 'RSVP', ctaEnabled: true };
    return { cta: 'View Event', ctaEnabled: true };
  }
  if (type === 'EXTERNAL') return { cta: 'Register', ctaEnabled: true };
  return { cta: 'View Event', ctaEnabled: true };
}

function shape(ev) {
  const dt = ev.dateAndTimeSettings || {};
  const f  = dt.formatted || {};
  const start = dt.startDate ? new Date(dt.startDate) : null;
  const loc = ev.location || {};
  const addr = (loc.address && loc.address.formatted) || '';

  return Object.assign({
    id: ev._id || ev.id,
    title: ev.title || '',
    shortDescription: ev.shortDescription || '',
    image: (ev.mainImage && (ev.mainImage.url || ev.mainImage)) || '',
    dateLine: f.dateAndTime || '',
    startDate: f.startDate || '',
    startMonth: start ? start.toLocaleString('en-US', { month: 'short' }) : '',
    startDay: start ? String(start.getDate()) : '',
    location: addr || loc.name || '',
    url: (ev.eventPageUrl && ev.eventPageUrl.path) || ''
  }, ctaFor(ev));
}

/**
 * Upcoming events (soonest first) and past events (most recent first).
 */
export async function getEvents() {
  try {
    const res = await elevatedQuery({ fields: ['DETAILS', 'TEXTS', 'REGISTRATION', 'URLS'] })
      .ne('status', 'CANCELED')
      .limit(50)
      .find();

    const all = (res.items || []).map(shape);
    const raw = res.items || [];

    const upcoming = [], past = [];
    raw.forEach((ev, i) => {
      const s = all[i];
      if (!s.url) return;
      if (ev.status === 'UPCOMING' || ev.status === 'STARTED') upcoming.push(s);
      else if (ev.status === 'ENDED') past.push(s);
    });

    upcoming.sort((a, b) => (a.dateLine > b.dateLine ? 1 : -1));
    past.reverse();

    return { upcoming, past: past.slice(0, 8) };
  } catch (err) {
    console.error('getEvents failed:', err);
    return { upcoming: [], past: [] };
  }
}

