/* Mock of the 'wix-data' module for the sample site: only what the Sermons
   page code uses (query('SiteSettings').eq('settingKey','sermonSeries').limit(1).find()). */
const F = () => window.ARISE_FIXTURES || {};
const C = () => window.__ARISE_BACKEND__ || {};
const wait = (ms) => new Promise((r) => setTimeout(r, ms));

function query(collection) {
  const st = { filters: [] };
  const api = {
    eq(field, value) { st.filters.push([field, value]); return api; },
    limit() { return api; },
    ascending() { return api; },
    async find() {
      await wait(200);
      let items = [];
      if (collection === 'SiteSettings') {
        const key = C().sermonSeries === undefined ? 'sermonSeries' : C().sermonSeries;
        const row = key && F()[key] ? Object.assign({ settingKey: 'sermonSeries' }, F()[key]) : null;
        if (row) items = [row];
      }
      st.filters.forEach(([f, v]) => { items = items.filter((r) => r[f] === v); });
      console.log('[mock wix-data] ' + collection + ' ->', items.length + ' rows');
      return { items };
    }
  };
  return api;
}

export default { query };

