1	/* ===========================================================================
2	   BACKEND UNIT TESTS  (node sample-site/tests/backend.test.mjs)
3	   Runs the real files in files2/arise-fixed-2026-09-14/backend/ under node by
4	   swapping the Wix modules for small mocks, and checks the behaviour the audit
5	   cared about: image conversion, event sorting and CTA states, form validation
6	   and the order of side effects. Zero dependencies.
7	   =========================================================================== */
8	import fs from 'node:fs';
9	import path from 'node:path';
10	import os from 'node:os';
11	import { pathToFileURL, fileURLToPath } from 'node:url';
12	import assert from 'node:assert/strict';
13	
14	const ROOT = path.resolve(new URL('.', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1'), '..', '..');
15	const BACKEND = path.join(ROOT, 'files2', 'arise-fixed-2026-09-14', 'backend');
16	const TMP = fs.mkdtempSync(path.join(os.tmpdir(), 'arise-backend-'));
17	
18	/* ---------- mocks ---------- */
19	const state = { inserted: [], contacts: [], triggers: [], events: [], programs: [], items: {}, collections: {} };
20	fs.writeFileSync(path.join(TMP, 'wix-web-module.mjs'), `
21	export const Permissions = { Anyone: 'Anyone' };
22	export const webMethod = (perm, fn) => fn;`);
