10	    .filter(function (h) { return h.getBoundingClientRect().width > 0; })
11	    .map(function (h) { return h.tagName + ' ' + h.textContent.trim().replace(/\s+/g, ' ').slice(0, 30); });
12	  r.h1 = document.querySelectorAll('h1').length;
13	  var ids = {};
14	  document.querySelectorAll('[id]').forEach(function (e) { ids[e.id] = (ids[e.id] || 0) + 1; });
15	  r.dupIds = Object.keys(ids).filter(function (k) { return ids[k] > 1; });
16	  document.querySelectorAll('img').forEach(function (i) {
17	    var s = i.getAttribute('src') || '';
18	    if (!i.hasAttribute('alt')) r.noAlt.push(s.slice(-40));
19	    if (s && i.complete && i.naturalWidth === 0) r.brokenImgs.push(s.replace('https://static.wixstatic.com/media/', '').slice(0, 60) + ' | alt=' + i.alt.slice(0, 30));
20	  });
21	  document.querySelectorAll('a,button,[role=button],input,select,textarea,summary').forEach(function (el) {
22	    var b = el.getBoundingClientRect(); if (!b.width || !b.height) return;
23	    var cs = getComputedStyle(el); if (cs.visibility === 'hidden' || el.closest('[hidden]')) return;
24	    if (b.height < 24 || b.width < 24) r.smallTaps.push((el.getAttribute('aria-label') || el.textContent || el.tagName).trim().replace(/\s+/g, ' ').slice(0, 24) + ' ' + Math.round(b.width) + 'x' + Math.round(b.height));
25	  });
26	  function lum(c) {
