(async () => {
  const routes = ['/', '/about', '/leaders', '/ministries', '/sermons', '/events', '/contact', '/arise-bible', '/serve', '/connect-groups', '/classes', '/creative-arts', '/praise-worship', '/childrens', '/youth', '/outreach', '/lead-network', '/arise-alexandria', '/_sample/service-times'];
  const out = [];
  for (const r of routes) {
    const f = document.createElement('iframe');
    f.style.cssText = 'position:fixed;left:-3000px;top:0;width:1366px;height:900px';
    f.src = '/_before' + r;
    document.body.appendChild(f);
    await new Promise(res => f.onload = res);
    await new Promise(res => setTimeout(res, 1500));
    try {
      const x = await f.contentWindow.__cmsTest({ full: true });
      out.push({ route: r, textHooks: x.textHooks, imageHooks: x.imageHooks, applied: x.applied, notApplied: x.notApplied.length, uncoveredText: x.uncoveredTextCount, uncoveredImages: x.uncoveredImageCount, notAppliedList: x.notApplied.slice(0, 4) });
    } catch (e) { out.push({ route: r, error: String(e) }); }
    f.remove();
  }
  const tot = out.reduce((a, o) => ({ hooks: a.hooks + (o.textHooks || 0) + (o.imageHooks || 0), unText: a.unText + (o.uncoveredText || 0), unImg: a.unImg + (o.uncoveredImages || 0) }), { hooks: 0, unText: 0, unImg: 0 });
  return { totals: tot, pages: out };
})()

