/* Dev-only helper for the render audit of the sample site. Not part of the
   Wix site. Call window.__audit() from the browser console. */

/* Error capture: this classic script runs before the deferred module scripts
   (elements, page code), so every uncaught error on the page is recorded. */
window.__errors = window.__errors || [];
window.addEventListener('error', function (e) {
  window.__errors.push((e.message || 'error') + ' @ ' + String(e.filename || '').split('/').pop() + ':' + (e.lineno || ''));
});
window.addEventListener('unhandledrejection', function (e) {
  window.__errors.push('unhandled rejection: ' + String(e.reason && (e.reason.message || e.reason)));
});

/* Visible snapshot of every arise-* element: text + image sources + hidden rows. */
window.__snapshot = function () {
  var out = {};
  document.querySelectorAll('*').forEach(function (e) {
    if (e.tagName.indexOf('ARISE-') !== 0) return;
    var imgs = Array.prototype.map.call(e.querySelectorAll('img'), function (i) { return i.getAttribute('src') || ''; });
    var hidden = Array.prototype.map.call(e.querySelectorAll('[data-ckrow]'), function (r) { return r.hidden ? 0 : 1; });
    out[e.tagName.toLowerCase() + '#' + (e.getAttribute('data-velo-id') || '')] = (e.innerText || '').replace(/\s+/g, ' ').trim() + ' |IMG| ' + imgs.join(',') + ' |ROWS| ' + hidden.join('');
  });
  document.querySelectorAll('body > .ahd-panel, body > .ast-panel').forEach(function (p, i) {
    out['panel' + i + '.' + p.className] = (p.textContent || '').replace(/\s+/g, ' ').trim();
  });
  return out;
};

function __diff(a, b) {
  var d = [];
  Object.keys(Object.assign({}, a, b)).forEach(function (k) {
    if (a[k] === b[k]) return;
    var x = a[k] || '', y = b[k] || '', i = 0;
    while (i < x.length && x[i] === y[i]) i++;
    d.push(k + ' @' + i + ': "' + x.slice(Math.max(0, i - 20), i + 40) + '" -> "' + y.slice(Math.max(0, i - 20), i + 40) + '"');
  });
  return d;
}
function __wait(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }

/* Re-mount test: Wix can detach and re-attach custom elements. Each element is
   removed and put back; the page must look the same, keep one copy of any
   body-level panel, and throw nothing. */
window.__remountTest = async function () {
  var before = window.__snapshot();
  var errs0 = window.__errors.length;
  var els = Array.prototype.slice.call(document.querySelectorAll('*')).filter(function (e) { return e.tagName.indexOf('ARISE-') === 0; });
  for (var i = 0; i < els.length; i++) {
    var el = els[i], parent = el.parentNode, next = el.nextSibling;
    parent.removeChild(el);
    await __wait(30);
    parent.insertBefore(el, next);
    await __wait(120);
  }
  await __wait(400);
  var after = window.__snapshot();
  return {
    url: location.pathname,
    elements: els.length,
    changed: __diff(before, after),
    headerPanels: document.querySelectorAll('body > .ahd-panel').length,
    serviceTimesPanels: document.querySelectorAll('body > .ast-panel').length,
    newErrors: window.__errors.slice(errs0)
  };
};

/* Round-trip test for new Page Content rows: merges the proposed rows (their
   text/image equal the built-in defaults) into the data-content each element
   already has, re-applies, and checks the page is unchanged. This is what
   happens on Wix the moment the CSV is imported. */
window.__roundTrip = async function (url) {
