    var x = a[k] || '', y = b[k] || '', i = 0;
    while (i < x.length && x[i] === y[i]) i++;
    d.push(k + ' @' + i + ': "' + x.slice(Math.max(0, i - 20), i + 40) + '" -> "' + y.slice(Math.max(0, i - 20), i + 40) + '"');
  });
