}
function __wait(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }

/* Re-mount test: Wix can detach and re-attach custom elements. Each element is
   removed and put back; the page must look the same, keep one copy of any
   body-level panel, and throw nothing. */
