(async () => {
  const main = ['/', '/about', '/leaders', '/ministries', '/sermons', '/events', '/contact', '/arise-bible', '/serve', '/connect-groups', '/classes', '/creative-arts', '/praise-worship', '/musicians', '/production', '/sound', '/media-team', '/content', '/childrens', '/youth', '/outreach', '/lead-network', '/arise-alexandria'];
  const extra = ['/_fixed/childrens-with-gallery', '/_fixed/outreach-with-gallery', '/_fixed/lead-network-with-gallery', '/_fixed/connect-groups-with-groups', '/_fixed/classes-with-classes', '/_fixed/home-with-news', '/_fixed/sermons-live', '/_fixed/service-times', '/_fixed/home-with-service-times'];
  const load = async (src, fn) => {
    const f = document.createElement('iframe');
    f.style.cssText = 'position:fixed;left:-3000px;top:0;width:1366px;height:900px';
    f.src = src; document.body.appendChild(f);
    await new Promise(r => f.onload = r);
    await new Promise(r => setTimeout(r, 1800));
    let out;
    try { out = await fn(f.contentWindow); } catch (e) { out = { error: String(e) }; }
    f.remove(); return out;
  };
  const sum = (w) => { const a = w.__audit(); return { overflow: a.overflow, h1: a.h1, empty: a.els.filter(e => /EMPTY/.test(e)), dupIds: a.dupIds, noAlt: a.noAlt.length, broken: a.brokenImgs.length, contrast: a.contrastCount, taps: a.smallTapsCount, errors: (w.__errors || []).slice() }; };
  const rows = [];
  for (const r of main.concat(extra)) {
    const fixed = await load(r, async (w) => { const s = sum(w); const rm = await w.__remountTest(); const cms = await w.__cmsTest(); return Object.assign(s, { remountChanged: rm.changed, panels: [rm.headerPanels, rm.serviceTimesPanels], remountErrors: rm.newErrors, cmsHooks: cms.hooks, cmsNotApplied: cms.notApplied, uncoveredText: cms.uncoveredTextCount, uncoveredImg: cms.uncoveredImageCount }); });
    const before = r.startsWith('/_fixed') ? null : await load('/_before' + r, async (w) => sum(w));
    const flag = [];
    if (fixed.error) flag.push('ERROR ' + fixed.error);
    else {
      if (fixed.errors.length) flag.push('js errors: ' + fixed.errors.join(' ; '));
      if (fixed.empty.length) flag.push('empty elements: ' + fixed.empty.join(','));
      if (fixed.remountChanged.length) flag.push('remount changed: ' + fixed.remountChanged.join(' ; ').slice(0, 300));
      if (fixed.remountErrors.length) flag.push('remount errors: ' + fixed.remountErrors.join(' ; '));
      if (fixed.panels[0] > 1 || fixed.panels[1] > 1) flag.push('duplicate panels ' + fixed.panels);
      if (fixed.cmsNotApplied.length) flag.push('cms not applied: ' + fixed.cmsNotApplied.slice(0, 5).join(' ; '));
      if (fixed.dupIds.length) flag.push('dup ids: ' + fixed.dupIds.join(','));
      if (before && !before.error) {
        ['overflow', 'noAlt', 'broken', 'contrast', 'taps'].forEach(k => { if (fixed[k] > before[k]) flag.push(k + ' worse: ' + before[k] + ' -> ' + fixed[k]); });
        if (fixed.h1 !== before.h1) flag.push('h1 count ' + before.h1 + ' -> ' + fixed.h1);
      }
    }
    rows.push({ route: r, ok: flag.length === 0, cmsHooks: fixed.cmsHooks, uncoveredText: fixed.uncoveredText, uncoveredImg: fixed.uncoveredImg, beforeErrors: before && before.errors ? before.errors.length : null, flags: flag });
  }
  return { pages: rows.length, failing: rows.filter(r => !r.ok).length, rows };
})()

