const fs = require('fs'), https = require('https');
const keys = ['childrens.kids.photo', 'childrens.superkid.logo', 'outreach.supplies.image', 'leadnetwork.austin.photo', 'leadnetwork.calloway.photo'];
const files = fs.readdirSync('.').filter((f) => /^arise-.*\.js$/.test(f));
const head = (u) => new Promise((r) => { try { https.request(u, { method: 'HEAD' }, (res) => r(res.statusCode)).on('error', () => r('err')).end(); } catch (e) { r('bad url'); } });
(async () => {
  for (const k of keys) {
    const f = files.find((x) => fs.readFileSync(x, 'utf8').includes('data-ci="' + k + '"'));
    const src = fs.readFileSync(f, 'utf8');
    const consts = {};
    (src.match(/const\s+([A-Z_][A-Z0-9_]*)\s*=\s*'([^']*)'/g) || []).forEach((m) => { const x = /const\s+([A-Z_][A-Z0-9_]*)\s*=\s*'([^']*)'/.exec(m); consts[x[1]] = x[2]; });
    const i = src.indexOf('data-ci="' + k + '"');
    const tagStart = src.lastIndexOf('<', i);
    const snippet = src.slice(tagStart, src.indexOf('>', i) + 1).replace(/\s+/g, ' ');
    let url = '';
    const m = /src="(?:'\s*\+\s*([A-Z_][A-Z0-9_]*)\s*\+\s*'|\$\{([A-Z_][A-Z0-9_]*)\}|([^"']+))/.exec(snippet);
    if (m) url = m[1] ? consts[m[1]] : m[2] ? consts[m[2]] : m[3];
    const code = url ? await head(url) : 'no url';
    console.log(k.padEnd(28) + ' ' + f.padEnd(22) + ' ' + (url || '?') + '  -> ' + code + '\n    ' + snippet.slice(0, 160));
  }
})();
