/* Mock of backend/content.web.js for the sample site (ES module).
   Returns the fixture the page asked for via window.__ARISE_BACKEND__, with a
   short delay so the element renders its fallback first, exactly as on Wix. */
const F = () => window.ARISE_FIXTURES || {};
const C = () => window.__ARISE_BACKEND__ || {};
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const pick = (key, dflt) => { const c = C(); const k = c[key]; if (k === undefined) return dflt; return F()[k] !== undefined ? F()[k] : dflt; };
const log = (fn, v) => { console.log('[mock backend] ' + fn + ' ->', Array.isArray(v) ? v.length + ' items' : (v && typeof v === 'object' ? Object.keys(v).length + ' keys' : v)); return v; };

export async function getPageContent() { await wait(300); return log('getPageContent', pick('pageContent', F().pageContent || {})); }
export async function getLeaders()     { await wait(300); return log('getLeaders', pick('leaders', F().leaders || [])); }
export async function getMinistries()  { await wait(300); return log('getMinistries', pick('ministries', F().ministries || [])); }
export async function getConnectGroups() { await wait(300); return log('getConnectGroups', pick('groups', [])); }
export async function getCreatives()   { await wait(300); return log('getCreatives', { departments: pick('depts', F().creativeDepts || []), members: pick('members', F().creativeMembers || []) }); }
export async function getServePositions() { await wait(300); return log('getServePositions', pick('positions', F().servePositions || [])); }
export async function getHomeSettings() { await wait(300); return log('getHomeSettings', pick('culture', F().homeCulture || null)); }

