window.__runPage = async (r, width, opts) => {
  width = width || 1366; opts = opts || {};
  const load = async (src, fn) => {
    const f = document.createElement('iframe');
    f.style.cssText = 'position:fixed;left:-4000px;top:0;width:' + width + 'px;height:900px;border:0';
    f.src = src; document.body.appendChild(f);
    await new Promise(res => { f.onload = res; setTimeout(res, 8000); });
    await new Promise(res => setTimeout(res, 1500));
    let out;
    try { out = await fn(f.contentWindow); } catch (e) { out = { error: String(e && e.message || e) }; }
    f.remove(); return out;
  };
  const sum = (w) => { const a = w.__audit(); return { overflow: a.overflow, h1: a.h1, empty: a.els.filter(e => /EMPTY/.test(e)), dupIds: a.dupIds, noAlt: a.noAlt.length, broken: a.brokenImgs.length, contrast: a.contrastCount, taps: a.smallTapsCount, errors: (w.__errors || []).slice() }; };
  const fixed = await load(r, async (w) => {
    const s = sum(w);
    const rm = await w.__remountTest();
    const rt = await w.__roundTrip();
    const cms = await w.__cmsTest();
    return Object.assign(s, { remountChanged: rm.changed, panels: [rm.headerPanels, rm.serviceTimesPanels], remountErrors: rm.newErrors, cmsHooks: cms.hooks, cmsNotApplied: cms.notApplied, uncoveredText: cms.uncoveredTextCount, uncoveredImg: cms.uncoveredImageCount, uncoveredSample: cms.uncoveredText.slice(0, 10), rtMerged: rt.merged, rtChanged: rt.changed, rtErrors: rt.errors.slice(s.errors.length) });
  });
  const before = (r.indexOf('/_fixed') === 0 || opts.noBefore) ? null : await load('/_before' + r, async (w) => sum(w));
  const flag = [];
  if (fixed.error) flag.push('ERROR ' + fixed.error);
  else {
    if (fixed.errors.length) flag.push('js errors: ' + fixed.errors.join(' ; '));
    if (fixed.empty.length) flag.push('empty elements: ' + fixed.empty.join(','));
    if (fixed.remountChanged.length) flag.push('remount changed: ' + fixed.remountChanged.join(' ; ').slice(0, 400));
    if (fixed.remountErrors.length) flag.push('remount errors: ' + fixed.remountErrors.join(' ; '));
    if (fixed.panels[0] > 1 || fixed.panels[1] > 1) flag.push('duplicate panels ' + fixed.panels);
    if (fixed.cmsNotApplied.length) flag.push('cms not applied (' + fixed.cmsNotApplied.length + '): ' + fixed.cmsNotApplied.slice(0, 6).join(' ; '));
    if (fixed.dupIds.length) flag.push('dup ids: ' + fixed.dupIds.join(','));
    if (fixed.rtChanged.length) flag.push('CSV import would change the page: ' + fixed.rtChanged.join(' ; ').slice(0, 600));
    if (fixed.rtErrors && fixed.rtErrors.length) flag.push('errors during CSV test: ' + fixed.rtErrors.join(' ; '));
    if (before && !before.error) {
      ['overflow', 'noAlt', 'broken', 'contrast', 'taps'].forEach(k => { if (fixed[k] > before[k]) flag.push(k + ' worse: ' + before[k] + ' -> ' + fixed[k]); });
      if (fixed.h1 !== before.h1) flag.push('h1 count ' + before.h1 + ' -> ' + fixed.h1);
    }
  }
  return { route: r, w: width, ok: flag.length === 0, hooks: fixed.cmsHooks, uncoveredText: fixed.uncoveredText, uncoveredImg: fixed.uncoveredImg, rtMerged: fixed.rtMerged, uncoveredSample: opts.showUncovered ? fixed.uncoveredSample : undefined, flags: flag };
};
window.__runMany = async (list, width, opts) => { const out = []; for (const r of list) out.push(await window.__runPage(r, width, opts)); return out; };
