(async () => {
  const check = async (src) => {
    const f = document.createElement('iframe');
    f.style.cssText = 'position:fixed;left:-4000px;top:0;width:1366px;height:900px;border:0';
    f.src = src; document.body.appendChild(f);
    await new Promise(res => { f.onload = res; setTimeout(res, 8000); });
    await new Promise(res => setTimeout(res, 1800));
    const d = f.contentDocument, el = d.querySelector('arise-connect');
    const vis = (n) => !!n && n.getClientRects().length > 0;
    const joinTab = el.querySelector('#acg-tab-connect-join');
    const joinPanel = el.querySelector('.panel[data-panel="connect-join"]');
    const hostPanel = el.querySelector('.panel[data-panel="connect-host"]');
    const goBtns = Array.from(el.querySelectorAll('.g__go'));
    const deadline = Array.from(el.querySelectorAll('[data-acg-hostby]'));
    const hostTab = el.querySelector('#acg-tab-connect-host');
    hostTab.focus();
    hostTab.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true }));
    const afterArrow = d.activeElement && d.activeElement.id;
    const out = { route: src, joinTabVisible: vis(joinTab), joinPanelHidden: joinPanel ? joinPanel.hidden : null, hostPanelOn: hostPanel && hostPanel.getAttribute('data-on'), joinButtonsVisible: goBtns.filter(vis).length + '/' + goBtns.length, deadlineVisible: deadline.filter(vis).length + '/' + deadline.length, tabText: (hostTab.innerText || '').replace(/\s+/g, ' ').trim(), whenCards: Array.from(el.querySelectorAll('.when__c')).filter(vis).length, focusAfterArrowRight: afterArrow, errors: (f.contentWindow.__errors || []).slice() };
    if (goBtns.length && vis(goBtns[0])) { goBtns[0].click(); await new Promise(r => setTimeout(r, 300)); out.afterJoinClickSelected = el.querySelector('.tab[aria-selected="true"]').id; out.joinPanelOn = joinPanel.getAttribute('data-on'); out.subjectPrefill = (el.querySelector('#connect-join-subject') || {}).value; }
    f.remove(); return out;
  };
  return [await check('/connect-groups'), await check('/_fixed/connect-groups-with-groups'), await check('/_fixed/connect-groups-join-open'), await check('/_fixed/connect-groups-no-deadline')];
})()

