  fs.writeFileSync(path.join(ROOT, 'sample-site', 'backend', 'shorts-fixture.js'),
    '/* Newest Shorts on the Arise Church channel, read ' + new Date().toISOString().slice(0, 10) + ' with the backend parser. */\n' +
    'export default ' + JSON.stringify(list.slice(0, 12), null, 1) + ';\n');
  fs.writeFileSync(path.join(S, 'shorts-latest.json'), JSON.stringify(list.slice(0, 12), null, 1));
