/* Analyse the Arise Church YouTube Shorts tab with the SAME parser the backend will use,
   against a saved copy and a live fetch with the live backend's User-Agent. Writes the
   sample fixture, the backend test fixture, and the newest 8 for the element fallback. */
const fs = require('fs');
const path = require('path');
const https = require('https');

const S = 'C:/Users/Rehch/AppData/Local/Temp/claude/D--projects-Arise-Church-Website/456ec4ba-6ded-42a6-8d3f-55dcfdade770/scratchpad';
const ROOT = 'D:/projects/Arise Church Website';
const CHANNEL_ID = 'UCGS9j7B_prcJkbTNgzlGrKg';

/* ---- parser (copied verbatim into backend/youtube.jsw) ---- */
function jsonText(raw) {
  try { return JSON.parse('"' + raw + '"'); } catch (e) { return raw; }
}
function parseShorts(html) {
  const out = [];
  const seen = {};
  const src = String(html || '');
  const add = function (id, title) {
    if (!id || seen[id] || !/^[A-Za-z0-9_-]{11}$/.test(id)) return;
    seen[id] = true;
    out.push({
      id: id,
      title: String(title || '').replace(/\s+/g, ' ').trim(),
      url: 'https://www.youtube.com/shorts/' + id,
      thumb: 'https://i.ytimg.com/vi/' + id + '/frame0.jpg'
    });
  };

  /* Current layout: shortsLockupViewModel blocks in the Shorts tab grid */
  const parts = src.split('"shortsLockupViewModel":');
  for (let i = 1; i < parts.length; i++) {
    const b = parts[i].slice(0, 8000);
    const idm = b.match(/shorts-shelf-item-([A-Za-z0-9_-]{11})/) ||
                b.match(/"reelWatchEndpoint":\{"videoId":"([A-Za-z0-9_-]{11})"/);
    if (!idm) continue;
    let title = '';
    const tm = b.match(/"primaryText":\{"content":"((?:[^"\\]|\\.)*)"/);
    if (tm) title = jsonText(tm[1]);
    if (!title) {
      const am = b.match(/"accessibilityText":"((?:[^"\\]|\\.)*)"/);
      if (am) title = jsonText(am[1]).replace(/,\s*[\d.,]+[KMB]?\s+views?\s*-\s*play Short\s*$/i, '');
    }
    add(idm[1], title);
  }

  /* Older layout: reelItemRenderer blocks */
  if (!out.length) {
    const old = src.split('"reelItemRenderer":');
    for (let j = 1; j < old.length; j++) {
      const b = old[j].slice(0, 6000);
      const idm = b.match(/"videoId":"([A-Za-z0-9_-]{11})"/);
      const hm = b.match(/"headline":\{"simpleText":"((?:[^"\\]|\\.)*)"/);
      if (idm) add(idm[1], hm ? jsonText(hm[1]) : '');
    }
  }
  return out;
}
/* ---- end parser ---- */

function get(url, ua) {
  return new Promise((resolve) => {
    const go = (u, hops) => {
      https.get(u, { headers: { 'User-Agent': ua, 'Accept-Language': 'en-US,en;q=0.9' } }, (res) => {
        if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location && hops < 5) {
          res.resume();
          return go(new URL(res.headers.location, u).href, hops + 1);
        }
        let d = '';
        res.setEncoding('utf8');
        res.on('data', (c) => { d += c; });
        res.on('end', () => resolve({ status: res.statusCode, url: u, body: d }));
      }).on('error', (e) => resolve({ status: 'error ' + e.message, url: u, body: '' }));
    };
    go(url, 0);
  });
}

(async () => {
  const saved = fs.readFileSync(path.join(S, 'yt-612f12.html'), 'utf8');
  const a = parseShorts(saved);
  console.log('saved page (Chrome UA): ' + a.length + ' Shorts');

  /* Sort chips on the Shorts tab */
  const chipRe = /"text":"(Latest|Popular|Oldest)"/g;
  let cm; const chipCtx = [];
  while ((cm = chipRe.exec(saved)) && chipCtx.length < 6) chipCtx.push(saved.slice(cm.index, cm.index + 220).replace(/"clickTrackingParams":"[^"]+",?/g, ''));
  console.log('sort chip snippets:\n  ' + (chipCtx.join('\n  ') || '(none)'));

  const liveCompat = await get('https://www.youtube.com/channel/' + CHANNEL_ID + '/shorts', 'Mozilla/5.0 (compatible)');
  const b = parseShorts(liveCompat.body);
  console.log('\nlive fetch with the backend UA "Mozilla/5.0 (compatible)": http ' + liveCompat.status + ', ' + liveCompat.body.length + ' bytes, ' + b.length + ' Shorts, final url ' + liveCompat.url);
  const liveChrome = await get('https://www.youtube.com/channel/' + CHANNEL_ID + '/shorts', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36');
  const c = parseShorts(liveChrome.body);
  console.log('live fetch with a Chrome UA: http ' + liveChrome.status + ', ' + c.length + ' Shorts');

  const list = b.length ? b : (c.length ? c : a);
  const same = b.length && c.length && b.slice(0, 8).map((x) => x.id).join() === c.slice(0, 8).map((x) => x.id).join();
  console.log('first 8 identical across UAs: ' + same);
  console.log('\nnewest Shorts (in page order):');
  list.slice(0, 12).forEach((x, i) => console.log('  ' + String(i + 1).padStart(2) + '  ' + x.id + '  ' + x.title));
  const noTitle = list.filter((x) => !x.title).length;
  console.log('Shorts without a parsed title: ' + noTitle + ' of ' + list.length);

  const old = ['GatBPIhEMg4', 'Gtu2W5uaBsw', '1FNbubTU_Sg', '9ius_ZgQuYA', '0ZF_-1g8Li8', 'dD0PrqHdmzM', 'J4T4YcOMAgc', 'zMLoS0O8YDM'];
  console.log('\ncurrent built-in clips, position in the Shorts tab: ' + old.map((o) => o + '@' + (list.findIndex((x) => x.id === o) + 1)).join('  '));

  const i = saved.indexOf('"shortsLockupViewModel"');
  console.log('\nfirst block (trimmed):\n' + saved.slice(i, i + 1800).replace(/"clickTrackingParams":"[^"]+",?/g, '').replace(/"playerParams":"[^"]+",?/g, ''));

  /* outputs */
  fs.mkdirSync(path.join(ROOT, 'sample-site', 'tests', 'fixtures'), { recursive: true });
  fs.writeFileSync(path.join(ROOT, 'sample-site', 'tests', 'fixtures', 'youtube-shorts.html'), liveCompat.body.length > 100000 ? liveCompat.body : saved);
  fs.writeFileSync(path.join(ROOT, 'sample-site', 'backend', 'shorts-fixture.js'),
    '/* Newest Shorts on the Arise Church channel, read ' + new Date().toISOString().slice(0, 10) + ' with the backend parser. */\n' +
    'export default ' + JSON.stringify(list.slice(0, 12), null, 1) + ';\n');
  fs.writeFileSync(path.join(S, 'shorts-latest.json'), JSON.stringify(list.slice(0, 12), null, 1));
  console.log('\nwrote sample-site/backend/shorts-fixture.js, sample-site/tests/fixtures/youtube-shorts.html, scratchpad/shorts-latest.json');
})();

