const C = () => window.__ARISE_BACKEND__ || {};
const wait = (ms) => new Promise((r) => setTimeout(r, ms));

export async function getLiveVideoId() { await wait(200); return C().liveVideoId || null; }
export async function getCurrentSeries() { await wait(200); return C().autoSeries || null; }
export async function getLatestShorts(limit) {
  await wait(250);
  const list = C().shorts === 'none' ? [] : SHORTS.slice(0, Math.max(1, Math.min(Number(limit) || 8, 24)));
  console.log('[mock backend] getLatestShorts ->', list.length + ' Shorts');
  return list;
}

