/* Sermons element: clips grid becomes the newest YouTube Shorts.
   Two-phase; every anchor must be found exactly once before anything is written. */
const fs = require('fs');
const S = 'C:/Users/Rehch/AppData/Local/Temp/claude/D--projects-Arise-Church-Website/456ec4ba-6ded-42a6-8d3f-55dcfdade770/scratchpad';
const D = 'D:/projects/Arise Church Website/files2/arise-fixed-2026-09-14';
const FILE = D + '/custom-elements/arise-sermons.js';
const MAN = D + '/cms/manifest/arise-sermons.json';

let s = fs.readFileSync(FILE, 'utf8');
if (s.includes('\r\n')) { console.error('ABORT: CRLF file, anchors assume LF'); process.exit(1); }
const once = (needle, label) => {
  const n = s.split(needle).length - 1;
  if (n !== 1) { console.error('ABORT ' + label + ': found ' + n + ' times'); process.exit(1); }
};
const replaceOnce = (a, b, label) => { once(a, label); s = s.split(a).join(b); };

/* 1. built-in CLIPS -> newest 8 Shorts */
const shorts = JSON.parse(fs.readFileSync(S + '/shorts-latest.json', 'utf8')).slice(0, 8);
if (shorts.length !== 8) { console.error('ABORT: need 8 Shorts'); process.exit(1); }
const start = s.indexOf('const CLIPS = [');
const end = s.indexOf('\n];\n', start);
if (start < 0 || end < 0) { console.error('ABORT: CLIPS block not found'); process.exit(1); }
const oldBlock = s.slice(start, end + 4);
if (oldBlock.indexOf('GatBPIhEMg4') < 0 || oldBlock.indexOf('zMLoS0O8YDM') < 0) { console.error('ABORT: CLIPS block not as expected'); process.exit(1); }
const newBlock =
  '/* Built-in Shorts list. Shown only until the page code sends the newest Shorts\n' +
  '   from the YouTube channel (data-clips), or if YouTube cannot be reached.\n' +
  '   These were the 8 newest Shorts on 14 Sept 2026. */\n' +
  'const CLIPS = [\n' +
  shorts.map(function (c) { return '  { id: ' + JSON.stringify(c.id) + ', title: ' + JSON.stringify(c.title) + ' }'; }).join(',\n') +
  '\n];\n';
s = s.slice(0, start) + newBlock + s.slice(end + 4);

/* 2. remove the old per-clip card builder in connectedCallback */
const cStart = s.indexOf('    const cards = CLIPS.map((c, i) =>');
const cEndMarker = "      '</a>').join('');\n";
const cEnd = s.indexOf(cEndMarker, cStart);
if (cStart < 0 || cEnd < 0) { console.error('ABORT: card builder not found'); process.exit(1); }
const cardsBlock = s.slice(cStart, cEnd + cEndMarker.length);
if (cardsBlock.indexOf('sermons.clips.item') < 0) { console.error('ABORT: card builder not as expected'); process.exit(1); }
s = s.slice(0, cStart) + s.slice(cEnd + cEndMarker.length).replace(/^\n/, '');

/* 3. grid mount */
replaceOnce(String.raw`'<div class="grid">' + cards + '</div>' +`,
  String.raw`'<div class="grid grid--shorts" id="aesClips" data-cms-source="YouTube"></div>' +`, 'grid mount');

/* 4. render on first build */
replaceOnce('    this.applyContent();\n\n    /* If the page code tells us a live stream is running, switch the player.',
  '    this.renderClips();\n    this.applyContent();\n\n    /* If the page code tells us a live stream is running, switch the player.', 'first render');

/* 5. observed attribute */
replaceOnce("static get observedAttributes() { return ['data-live-video',",
  "static get observedAttributes() { return ['data-clips', 'data-live-video',", 'observedAttributes');

/* 6. attribute change */
replaceOnce("    if (name === 'data-content') { this.applyContent(); return; }\n",
  "    if (name === 'data-content') { this.applyContent(); return; }\n    if (name === 'data-clips') { this.renderClips(); return; }\n", 'attributeChangedCallback');

/* 7. renderClips method */
replaceOnce('  /* Series band, driven from the SiteSettings collection by the page code.',
  String.raw`  /* Shorts grid. The page code sends the newest Shorts from the YouTube channel
     as data-clips: [{ id, title }]. Until then, or if YouTube cannot be reached,
     the built-in CLIPS list shows. Each card opens the Short on YouTube. */
  renderClips() {
    const mount = this.querySelector('#aesClips');
    if (!mount) return;
    let list = [];
    const raw = this.getAttribute('data-clips');
    if (raw) {
      try { list = JSON.parse(raw); } catch (e) { console.error('arise-sermons: bad data-clips JSON', e); list = []; }
    }
    if (!Array.isArray(list)) list = [];
    list = list.filter(function (c) { return c && /^[A-Za-z0-9_-]{11}$/.test(String(c.id || '')); }).slice(0, 12);
    if (!list.length) list = CLIPS;
    const key = list.map(function (c) { return c.id + '|' + (c.title || ''); }).join(',');
    if (this._clipsKey === key && mount.children.length) return;
    this._clipsKey = key;
    mount.innerHTML = list.map(function (c) {
      const title = String(c.title || '').replace(/\s+/g, ' ').trim();
      return '<a class="card" href="https://www.youtube.com/shorts/' + c.id + '" target="_blank" rel="noopener">' +
        '<div class="card__th card__th--short">' +
          '<img src="' + YT + c.id + '/frame0.jpg" alt="' + asrEsc(title || 'Arise Church Short') + '" loading="lazy">' +
        '</div>' +
        (title ? '<h3>' + asrEsc(title) + '</h3>' : '') +
      '</a>';
    }).join('');
  }

  /* Series band, driven from the SiteSettings collection by the page code.`, 'renderClips method');

/* 8. CSS for vertical Short cards */
replaceOnce('.aes .card p{font-size:13.5px;color:var(--muted);line-height:1.6;margin-top:8px}\n',
  '.aes .card p{font-size:13.5px;color:var(--muted);line-height:1.6;margin-top:8px}\n' +
  '.aes .card__th--short{aspect-ratio:9/16}\n' +
  '.aes .grid--shorts{grid-template-columns:repeat(4,1fr);gap:28px 20px}\n' +
  '@media(max-width:760px){.aes .grid--shorts{grid-template-columns:repeat(2,1fr);gap:24px 14px}}\n', 'css');

/* 9. header note */
replaceOnce('   CMS hooks 2026-09-14: every text block and image editable via Page Content (see cms/manifest/arise-sermons.json)',
  '   CMS hooks 2026-09-14: every text block and image editable via Page Content (see cms/manifest/arise-sermons.json)\n' +
