if (s.indexOf('sermons.clips.item') > -1) { console.error('ABORT: per-clip hooks still present'); process.exit(1); }

/* manifest: drop per-clip rows */
const m = JSON.parse(fs.readFileSync(MAN, 'utf8'));
const kept = m.filter(function (r) { return !/^sermons\.clips\.item\d+\./.test(r.contentKey); });
const removed = m.length - kept.length;

fs.writeFileSync(FILE, s);
