/* Does the live getCurrentSeries parser work on the desktop playlists page, and what
   would a parser for YouTube's current lockupViewModel layout return? */
const fs = require('fs');
const S = 'C:/Users/Rehch/AppData/Local/Temp/claude/D--projects-Arise-Church-Website/456ec4ba-6ded-42a6-8d3f-55dcfdade770/scratchpad';

const IGNORE = ['sunday sermons', 'lead network', 'iserve september', 'glory nights | arise church',
  'conferences & special events', 'apostle bryant sanders - messages'];

/* the live algorithm, verbatim */
function liveSeries(html) {
  const seen = {};
  const re = /"playlistId":"(PL[A-Za-z0-9_-]{10,})"/g;
  let m;
  while ((m = re.exec(html)) !== null) {
    const pid = m[1];
    if (seen[pid]) continue;
    seen[pid] = true;
    const seg = html.slice(m.index, m.index + 3000);
    const t = seg.match(/"title":\{"runs":\[\{"text":"([^"]{2,90})"/) ||
              seg.match(/"title":\{"simpleText":"([^"]{2,90})"/);
    if (!t) continue;
    const title = t[1].trim();
    const lower = title.toLowerCase();
    if (IGNORE.indexOf(lower) > -1) continue;
    if (lower.indexOf('series') === -1) continue;
    return { title: title.replace(/\s*\(series\)\s*$/i, '').trim(), url: 'https://www.youtube.com/playlist?list=' + pid };
  }
  return null;
}

function jsonText(raw) { try { return JSON.parse('"' + raw + '"'); } catch (e) { return raw; } }

/* candidate: every playlist on the tab, in page order, from either layout */
function listPlaylists(html) {
  const out = [];
  const seen = {};
  const parts = String(html || '').split('"lockupViewModel":');
  for (let i = 1; i < parts.length; i++) {
    const b = parts[i].slice(0, 9000);
    const idm = b.match(/"contentId":"(PL[A-Za-z0-9_-]{10,})"/);
    const tm = b.match(/"lockupMetadataViewModel":\{"title":\{"content":"((?:[^"\\]|\\.)*)"/) ||
               b.match(/"title":\{"content":"((?:[^"\\]|\\.)*)"/);
    if (!idm || !tm || seen[idm[1]]) continue;
    seen[idm[1]] = true;
    out.push({ id: idm[1], title: jsonText(tm[1]).trim() });
  }
  if (!out.length) {
    const re = /"playlistId":"(PL[A-Za-z0-9_-]{10,})"/g;
    let m;
    while ((m = re.exec(html)) !== null) {
      if (seen[m[1]]) continue;
      const seg = html.slice(m.index, m.index + 3000);
      const t = seg.match(/"title":\{"runs":\[\{"text":"((?:[^"\\]|\\.)*)"/) || seg.match(/"title":\{"simpleText":"((?:[^"\\]|\\.)*)"/);
      if (!t) continue;
      seen[m[1]] = true;
      out.push({ id: m[1], title: jsonText(t[1]).trim() });
    }
  }
  return out;
}

for (const f of ['yt-playlists-compatible.html', 'yt-playlists-desktop.html']) {
  const html = fs.readFileSync(S + '/' + f, 'utf8');
  console.log('=== ' + f);
  console.log('  live parser result: ' + JSON.stringify(liveSeries(html)));
  const list = listPlaylists(html);
  console.log('  playlists found by the candidate parser: ' + list.length);
  list.forEach((p, i) => console.log('    ' + String(i + 1).padStart(2) + '  ' + p.id + '  ' + p.title));
  const sorted = /"text":"(Date added \(newest\)|Last video added)"[^}]{0,80}"selected":true/.exec(html) || /"title":"(Date added \(newest\)|Last video added)"/.exec(html);
  console.log('  sort hint: ' + (sorted ? sorted[1] : '(none found)'));
  const i = html.indexOf('"lockupViewModel":');
  if (i > -1) console.log('  first lockup block (trimmed): ' + html.slice(i, i + 1400).replace(/"clickTrackingParams":"[^"]+",?/g, '').replace(/"trackingParams":"[^"]+",?/g, ''));
}

