(async () => {
  const inspect = async (src, width) => {
    const f = document.createElement('iframe');
    f.style.cssText = 'position:fixed;left:-4000px;top:0;width:' + width + 'px;height:900px;border:0';
    f.src = src; document.body.appendChild(f);
    await new Promise(r => { f.onload = r; setTimeout(r, 8000); });
    await new Promise(r => setTimeout(r, 2000));
    const d = f.contentDocument, el = d.querySelector('arise-sermons');
    const grid = el.querySelector('#aesClips');
    const cards = Array.from(grid.querySelectorAll('a.card'));
    const th = cards[0] && cards[0].querySelector('.card__th');
    const r = th ? th.getBoundingClientRect() : null;
    const out = { route: src, width, dataClips: el.hasAttribute('data-clips'), cards: cards.length, source: grid.getAttribute('data-cms-source'), columns: getComputedStyle(grid).gridTemplateColumns.split(' ').length, firstTitle: cards[0] && cards[0].querySelector('h3') && cards[0].querySelector('h3').textContent, firstHref: cards[0] && cards[0].getAttribute('href'), firstImg: cards[0] && cards[0].querySelector('img').getAttribute('src'), thumbRatio: r ? (r.height / r.width).toFixed(2) : null, imgsLoaded: cards.filter(c => { const i = c.querySelector('img'); return i.complete && i.naturalWidth > 0; }).length, errors: (f.contentWindow.__errors || []).slice() };
    f.remove(); return out;
  };
  return [await inspect('/sermons', 1366), await inspect('/_fixed/sermons-no-shorts', 1366), await inspect('/sermons', 390)];
})()

