async function() {
  const wanted = [
    'childrens.kids.photo',
    'childrens.superkid.logo',
    'outreach.supplies.image',
    'leadnetwork.austin.photo',
    'leadnetwork.calloway.photo',
    'connect.season.hostby',
    'alexandria.pastor.bio2'
  ];
  const body = {
    dataCollectionId: 'PageContent',
    query: {
      paging: {
        limit: 100
      }
    }
  };
  const res = await wix.request({
    method: 'POST',
    url: 'https://www.wixapis.com/wix-data/v2/items/query',
    body: body
  });
  const items = (res && res.dataItems) || [];
  const fieldNames = {};
  items.forEach(function (it) {
    Object.keys(it.data || {}).forEach(function (k) {
      fieldNames[k] = true;
    });
  });
  const rows = items
    .filter(function (it) { return wanted.indexOf((it.data || {}).contentKey) > -1; })
    .map(function (it) {
      const d = it.data || {};
      return {
        id: it.id,
        contentKey: d.contentKey,
        text: String(d.text || '').slice(0, 80),
        imageUrl: d.imageUrl || '',
        imageField: d.image ? 'set' : 'empty'
      };
    });
  return {
    totalRows: items.length,
    pagingMetadata: res.pagingMetadata,
    fields: Object.keys(fieldNames).sort(),
    rows: rows
  };
}

