                "state": "California",
                "year": 2022,
                "city": "San Francisco",
                "population": 840000
            }
        }
    ],
    "returnEntity": true
}'
```
--- Method Response Shape ---

## Method Response Shape

```json
{
  "results": [
    "object"
  ],
  "bulkActionMetadata": {
    "totalSuccesses": "integer",
