async function() {
  const keys = [];
  let offset = 0;
  for (let page = 0; page < 10; page++) {
    const body = {
      dataCollectionId: "PageContent",
      query: {
        paging: {
          limit: 1000,
          offset: offset
        }
      }
    };
    const res = await wix.request({
      method: "POST",
      url: "https://www.wixapis.com/wix-data/v2/items/query",
      body: body
    });
    const items = (res.dataItems || []);
    items.forEach((it) => keys.push(it.data.contentKey));
    if (items.length < 1000) break;
    offset += items.length;
  }
  return {
    count: keys.length,
    keys: keys.sort()
  };
}

