async function() {
  const ROWS = [
["youth.cta.button","youth","Get involved box button","Plan Your Visit","","Red box at the bottom, white button"],
["youth.cta.campus1","youth","Box first campus words","in Pineville,","","Red box at the bottom, after the first time"],
["youth.cta.campus2","youth","Box second campus words","in Alexandria.","","Red box at the bottom, after the second time"],
["youth.cta.heading","youth","Get involved box heading","Come Hang Out","","Red box at the bottom, title"],
["youth.cta.kicker","youth","Get involved box kicker","Get Involved","","Red box at the bottom, small text"],
["youth.events.emptyBody","youth","Events empty-box text","Youth events will appear here as they are announced.","","Events section, dashed box text"],
["youth.events.emptyHeading","youth","Events empty-box heading","Nothing listed yet","","Events section, dashed box title"],
["youth.events.heading","youth","Events heading","Youth Events","","Events section title"],
["youth.events.kicker","youth","Events kicker","Youth Events","","Events section, small red text"],
["youth.hero.heading","youth","Hero heading","Youth Ministry","","Top of page, big title"],
["youth.hero.kicker","youth","Hero kicker","6th to 12th Grade","","Top of page, small red text above the big title"],
["youth.leaders.heading","youth","Leaders heading","Our Leaders","","Leaders section title"],
["youth.leaders.kicker","youth","Leaders kicker","Our Leaders","","Leaders section, small red text"],
["youth.leaders.name","youth","Leaders names","Chad and Tabitha Kerik","","Leaders section, names on the card"],
["youth.leaders.photo","youth","Leaders photo","","https://static.wixstatic.com/media/1f9fa2_4fb0f121cb08443a8ca1f72286449c12~mv2.png","Leaders section, photo on the card"],
["youth.leaders.role","youth","Leaders role badge","Youth Ministers","","Leaders section, red badge on the card"],
["youth.moments.heading","youth","Photos heading","Youth Life","","Photo section title"],
["youth.moments.kicker","youth","Photos kicker","Moments","","Photo section, small red text"]
  ];
  const existing = new Set();
  let offset = 0;
  for (let p = 0; p < 10; p++) {
    const qBody = {
      dataCollectionId: "PageContent",
      query: {
        paging: {
          limit: 1000,
          offset: offset
        }
      }
    };
    const res = await wix.request({
      method: "POST",
      url: "https://www.wixapis.com/wix-data/v2/items/query",
      body: qBody
    });
    const items = res.dataItems || [];
    items.forEach((it) => existing.add(it.data.contentKey));
    if (items.length < 1000) break;
    offset += items.length;
  }
  const toInsert = ROWS.filter((r) => !existing.has(r[0])).map((r) => ({
    data: {
      contentKey: r[0],
      page: r[1],
      label: r[2],
      text: r[3],
      imageUrl: r[4],
      where: r[5]
    }
  }));
  if (!toInsert.length) {
    return {
      rows: ROWS.length,
      attempted: 0,
      skippedExisting: ROWS.length
    };
  }
  const insBody = {
    dataCollectionId: "PageContent",
    dataItems: toInsert
  };
  const ins = await wix.request({
    method: "POST",
    url: "https://www.wixapis.com/wix-data/v2/bulk/items/insert",
    body: insBody
  });
  const meta = ins.bulkActionMetadata || {};
  const failures = (ins.results || []).filter((x) => x.itemMetadata && !x.itemMetadata.success).map((x) => ({
    index: x.itemMetadata.originalIndex,
    error: x.itemMetadata.error
  }));
  return {
    rows: ROWS.length,
    attempted: toInsert.length,
    skippedExisting: ROWS.length - toInsert.length,
    successes: meta.totalSuccesses,
    failures: meta.totalFailures,
    failureDetail: failures.slice(0, 5)
  };
}

