// Summarise the speed-fix preview checks against the live site.
// node analyze-speed.js functional   -> correctness of the speed preview vs live (after-publish)
// node analyze-speed.js timing       -> first-visit loading numbers, preview vs live
const fs = require('fs');
const path = require('path');
const ROOT = 'D:/projects/Arise Church Website/audit/preview-check-2026-09-15';
const mode = process.argv[2] || 'functional';
const read = (p) => { try { return JSON.parse(fs.readFileSync(p, 'utf8')); } catch (e) { return null; } };
const el = (r, t) => ((r && r.arise) || []).find((a) => a.tag === t) || { text: '', links: [], tabsVisible: [], clips: [], brokenImgs: [], imgSources: [] };

if (mode === 'functional') {
  const P = path.join(ROOT, 'speed-functional', 'preview');
  const L = path.join(ROOT, 'after-publish', 'live');
  const files = fs.readdirSync(P).filter((f) => f.endsWith('.json')).sort();
  const out = [];
  let broken = 0, textDiffs = [], exc = [], warn = [], unresized = [], lazyTop = [];
  for (const f of files) {
    const p = read(path.join(P, f)), l = read(path.join(L, f));
    (p.arise || []).forEach((a) => {
      broken += a.brokenImgs.length;
      a.brokenImgs.forEach((b) => out.push('BROKEN ' + f + ' ' + b));
      (a.imgSources || []).forEach((s) => { if (/static\.wixstatic\.com\/media\/[^/]+\.(jpe?g|png|webp)$/i.test(s.src)) unresized.push(f + ' ' + a.tag + ' ' + s.src.slice(-60)); });
      const b = el(l, a.tag);
      if (l && Math.abs(a.textLen - b.text.length) > Math.max(20, b.text.length * 0.03)) textDiffs.push(f + ' ' + a.tag + ' preview ' + a.textLen + ' vs live ' + b.text.length);
    });
    p.exceptions.filter((e) => !/firebase|AssistantLoadState|React error #421|Uncaught \(in promise\)/i.test(e)).forEach((e) => exc.push(f + ': ' + e.slice(0, 120)));
    p.console.filter((c) => /warn|error/.test(c.type) && /^[A-Z][A-Za-z' &!]+: |Site content|custom element/.test(c.text) && !/Permissions policy|Failed to load resource/.test(c.text)).forEach((c) => warn.push(f + ': ' + c.text.slice(0, 120)));
    if (p.error) out.push('ERROR ' + f + ' ' + p.error);
    const sc = p.console.find((c) => /^Site content -> /.test(c.text));
    if ((p.arise || []).length && !sc) out.push('NO "Site content ->" line: ' + f);
    else if (sc) {
      const n = (sc.text.match(/#/g) || []).length;
      if (n < (p.arise || []).length) out.push('Site content reached ' + n + ' of ' + (p.arise || []).length + ' elements: ' + f + ' (' + sc.text + ')');
    }
  }
  const R = (k, v) => read(path.join(P, k + '-' + (v || 'desktop') + '.json'));
  const ok = (n, c, d) => out.push((c ? 'PASS ' : 'FAIL ') + n + (d ? '  [' + d + ']' : ''));
  const ce = el(R('connect-groups'), 'arise-connect');
  ok('Connect: only Host tab, Sept 20, no Join', ce.tabsVisible.length === 1 && /September 20/.test(ce.text) && ce.joinButtonsVisible === 0);
  const he = el(R('home'), 'arise-home');
  ok('Home times + no doubled day', /Sunday Service\s*10:30 AM/i.test(he.text) && !/Sunday\s+Sunday/i.test(he.text) && /Bible Study[\s\S]{0,40}6:45 PM/i.test(he.text));
  ok('Home: culture/news logs present', R('home').console.some((c) => /culture video/.test(c.text)) && R('home').console.some((c) => /news \d+ items/.test(c.text)));
  const se = el(R('sermons'), 'arise-sermons');
  ok('Sermons: 8 Shorts, series, Latest Service', se.clips.length === 8 && /Kingdom/i.test(se.text) && /Latest Service/.test(se.text));
  const bb = R('arise-bible');
  ok('Bible Search John 3:16', bb.bibleSearch && /For God so loved/i.test(bb.bibleSearch.text || ''));
  ok('Contact: no Sunday Sunday', !R('contact').sundaySunday);
  ok('Serve: 7 positions', R('serve').console.some((c) => /7 positions/.test(c.text)));
  ok('Leaders: 7 leaders logged', R('leaders').console.some((c) => /7 leaders/.test(c.text)));
  ok('Alexandria: Prophet Vanessa Sanders', /Prophet Vanessa Sanders/.test(el(R('arise-alexandria'), 'arise-alexandria').text));
  console.log(out.join('\n'));
  console.log('\npages: ' + files.length + ' | broken images: ' + broken + ' | unresized wixstatic <img>: ' + unresized.length + ' | unexpected exceptions: ' + exc.length + ' | warnings from our code: ' + warn.length + ' | text differences vs live: ' + textDiffs.length);
  unresized.slice(0, 10).forEach((x) => console.log('  UNRESIZED ' + x));
  exc.slice(0, 10).forEach((x) => console.log('  EXC ' + x));
  warn.slice(0, 10).forEach((x) => console.log('  WARN ' + x));
  textDiffs.slice(0, 20).forEach((x) => console.log('  TEXT ' + x));
}

if (mode === 'timing') {
  const T = path.join(ROOT, 'speed-timing');
  const rows = {};
  for (const site of ['preview', 'live']) {
    for (const f of fs.readdirSync(path.join(T, site)).filter((x) => x.endsWith('.json'))) {
      const r = read(path.join(T, site, f));
      const key = r.key + ' ' + r.viewport;
      const t = r.timing || {};
      const els = t.elements || {};
      const texts = Object.values(els).map((e) => e.text).filter((x) => x !== undefined);
      const settled = Object.values(els).map((e) => e.lastRender || 0);
      const img = (t.byType || {}).img || { n: 0, kb: 0 };
      const all = Object.values(t.byType || {}).reduce((s, x) => s + x.kb, 0);
      (rows[key] = rows[key] || { preview: [], live: [] })[site].push({
        load: t.load, lcp: t.lcp, text: texts.length ? Math.min.apply(null, texts) : null,
        settled: settled.length ? Math.max.apply(null, settled) : null, imgKB: img.kb, imgN: img.n, totalKB: all,
        backend: (r.backendCalls || []).map((b) => b.fn.split('/').pop() + ' ' + b.startMs + '+' + b.ms)
      });
    }
  }
  const avg = (a, k) => { const v = a.map((x) => x[k]).filter((x) => typeof x === 'number' && x > 0); return v.length ? Math.round(v.reduce((s, x) => s + x, 0) / v.length) : '-'; };
  const cols = ['load', 'lcp', 'text', 'settled', 'imgKB', 'totalKB'];
  console.log('page/viewport'.padEnd(22) + cols.map((c) => ('live ' + c).padStart(13) + ('prev ' + c).padStart(13)).join(''));
  const summary = { live: {}, preview: {} };
  Object.keys(rows).sort().forEach((k) => {
    const r = rows[k];
    console.log(k.padEnd(22) + cols.map((c) => String(avg(r.live, c)).padStart(13) + String(avg(r.preview, c)).padStart(13)).join(''));
    cols.forEach((c) => { ['live', 'preview'].forEach((s) => { const v = avg(r[s], c); if (v !== '-') (summary[s][c] = summary[s][c] || []).push(v); }); });
  });
  console.log('\nbackend call timings (ms from navigation start + duration):');
  Object.keys(rows).sort().forEach((k) => console.log('  ' + k.padEnd(20) + ' live: ' + (rows[k].live[0] || { backend: [] }).backend.join(', ') + '\n  ' + ''.padEnd(20) + ' prev: ' + (rows[k].preview[0] || { backend: [] }).backend.join(', ')));
  console.log('\ntotals across pages (sum of per-page averages):');
  cols.forEach((c) => { const s = (x) => (summary[x][c] || []).reduce((a, b) => a + b, 0); console.log('  ' + c.padEnd(8) + ' live ' + s('live') + '  preview ' + s('preview')); });
}

