  const schema = await getResourceSchemaByUrl("https://dev.wix.com/docs/api-reference/business-management/online-programs/programs/create-program");
  const create = schema.methods.find((m) => /CreateProgram/i.test(m.name || m.operationId || ""));
  const comp = schema.components && schema.components.schemas ? schema.components.schemas : {};
  const pick = ["Program", "Description", "Timeline", "Restrictions", "Price", "Seo", "ProgramImage", "Image", "Schedule", "SelfPaced", "TimelineOneOf"];
  const out = {};
  Object.keys(comp).forEach((k) => {
    if (pick.some((p) => k.toLowerCase().includes(p.toLowerCase()))) out[k] = comp[k];
  });
  return {
    methodRequest: create ? create.request || create.requestBody : null,
    componentKeys: Object.keys(comp),
    components: out
  };
}

