async function() {
  const schema = await getResourceSchemaByUrl("https://dev.wix.com/docs/api-reference/business-management/online-programs/programs/create-program");
  const prog = schema.methods
    ? null
    : null;
  const req = (schema.methods || []).map((m) => m.name);
  const body = schema;
  // Narrow to the CreateProgram request body's program object
  const find = (obj, depth) => {
    if (!obj || depth > 8 || typeof obj !== "object") return null;
    if (obj.title === "CreateProgramRequest") return obj;
    for (const k of Object.keys(obj)) {
      const hit = find(obj[k], depth + 1);
      if (hit) return hit;
    }
    return null;
  };
  const createReq = find(body, 0);
  const p = createReq && createReq.properties && createReq.properties.program
    ? createReq.properties.program.properties
    : {};
  const trim = (x) => JSON.parse(JSON.stringify(x || null).slice(0, 4000));
  return {
    methods: req.slice(0, 20),
    timeline: trim(p.timeline),
    price: trim(p.price),
    restrictionsKeys: p.restrictions && p.restrictions.properties ? Object.keys(p.restrictions.properties) : null,
    descriptionKeys: p.description && p.description.properties ? Object.keys(p.description.properties) : null,
    descriptionImage: trim(p.description && p.description.properties && p.description.properties.image)
  };
}

