1	/* ===========================================================================
2	   ARISE CHURCH -- CLASSES
3	   File: public/custom-elements/arise-classes.js
4	   Tag:  arise-classes
5	   CMS hooks 2026-09-14: every text block and image editable via Page Content (see cms/manifest/arise-classes.json)
6	
7	   Lists every published Online Program. Free or paid is decided in the
8	   Online Programs dashboard, not here -- this page shows whatever they set,
9	   and updates itself when they change it.
10	
11	   INSTALL
12	   1. Velo sidebar -> Public -> custom-elements/ -> new file arise-classes.js
13	      -> paste this whole file
14	   2. Editor -> the Classes page -> Add (+) -> Embed Code -> Custom Element
15	      Choose Source -> Velo file -> arise-classes.js
16	      Tag Name: arise-classes
17	   3. STRETCH IT FULL WIDTH. Give it plenty of height.
18	   4. Add the backend function and page code -- see CLASSES-SETUP.md
19	   5. Save, then PUBLISH. Check the LIVE page.
20	
21	   With no published programs it shows a "coming soon" panel rather than an
22	   empty page, so it is safe to publish before the first class exists.
23	   =========================================================================== */
24	
25	const ACL_FONTS =
26	  'https://fonts.googleapis.com/css2?family=Anton&family=Oswald:wght@300;400;500;600&display=swap';
27	
28	const ACL_CSS = `
29	arise-classes{display:block;width:100%}
30	.acl *{box-sizing:border-box;margin:0;padding:0}
31	.acl{
32	  --red:#D6222D;--redL:#DB3F48;--ink:#0A0A0C;--scrim:#060608;--paper:#fff;
33	  --bone:#F4F2F0;--muted:#6A6A6E;--rule:rgba(10,10,12,.12);--ruleD:rgba(255,255,255,.15);
