async function() {
  const ROWS = [
    ["classes.detail.back", "classes", "Class page: back link", "All Classes", "", "Class page, red link above the flyer"],
    ["classes.detail.whenLabel", "classes", "Class page: When label", "When", "", "Class page, small red label beside the dates"],
    ["classes.detail.note", "classes", "Class page: foyer sign-up note", "You can also sign up on the registration sheets in the foyer.", "", "Class page, line with the red bar above the buttons"],
    ["classes.detail.register", "classes", "Class page: register button", "Register for this Class", "", "Class page, red button"],
    ["classes.detail.ask", "classes", "Class page: questions button", "Ask a Question", "", "Class page, outlined button next to Register"]
  ];
  const existing = new Set();
  let offset = 0;
  for (let p = 0; p < 10; p++) {
    const qBody = {
      dataCollectionId: "PageContent",
      query: {
        paging: {
          limit: 1000,
          offset: offset
        }
      }
    };
    const res = await wix.request({
      method: "POST",
      url: "https://www.wixapis.com/wix-data/v2/items/query",
      body: qBody
    });
    const items = res.dataItems || [];
    items.forEach((it) => existing.add(it.data.contentKey));
    if (items.length < 1000) break;
    offset += items.length;
  }
  const toInsert = ROWS.filter((r) => !existing.has(r[0])).map((r) => ({
    data: {
      contentKey: r[0],
      page: r[1],
      label: r[2],
      text: r[3],
      imageUrl: r[4],
      where: r[5]
    }
  }));
  if (!toInsert.length) {
    return {
      rows: ROWS.length,
      attempted: 0,
      skippedExisting: ROWS.length
    };
  }
  const ins = await wix.request({
    method: "POST",
    url: "https://www.wixapis.com/wix-data/v2/bulk/items/insert",
    body: {
      dataCollectionId: "PageContent",
      dataItems: toInsert
    }
  });
  const meta = ins.bulkActionMetadata || {};
  return {
    rows: ROWS.length,
    attempted: toInsert.length,
    successes: meta.totalSuccesses,
    failures: meta.totalFailures,
    totalRowsNow: existing.size + (meta.totalSuccesses || 0)
  };
}

