T="C:/Users/Rehch/.claude/projects/D--projects-Arise-Church-Website/456ec4ba-6ded-42a6-8d3f-55dcfdade770.jsonl"; echo "== scanning $(du -m "$T" | cut -f1) MB transcript for personal details =="; node -e "
const fs=require('fs');const rl=require('readline').createInterface({input:fs.createReadStream('$T')});
let lines=0; const hits={emails:new Set(), phones:new Set(), formRows:0, submissions:0};
rl.on('line',l=>{lines++;
  (l.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[a-z]{2,}/g)||[]).forEach(e=>{ if(!/arisenow|arisechurchprayer|dyerbradly|noreply|example|wix|googlegroups|sentry|firebase/i.test(e)) hits.emails.add(e.toLowerCase()); });
  (l.match(/\b\(?\d{3}\)?[ .-]\d{3}[ .-]\d{4}\b/g)||[]).forEach(p=>{ if(!/640.?1865/.test(p)) hits.phones.add(p); });
  if(/ArchivedFormSubmissions|Import1/.test(l)) hits.formRows++;
  if(/submissions/i.test(l) && /firstName|lastName/i.test(l)) hits.submissions++;
});
rl.on('close',()=>{ console.log('lines:',lines);
  console.log('other peoples emails:',hits.emails.size, [...hits.emails].slice(0,5).map(e=>e.replace(/^(..).*@/,'\$1***@')).join(' '));
  console.log('phone-like numbers (not the church):',hits.phones.size,[...hits.phones].slice(0,3).map(p=>p.slice(0,3)+'***').join(' '));
  console.log('lines mentioning form-submission collections:',hits.formRows,'| lines with name fields:',hits.submissions);
});"

